window.__LEX={"G200":"<h1>akris</h1>\n<p>Strong n° 200 <i>Prononciation [ak-rece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sauterelle (Angl. : locuste) infestant les régions d'orient, détruisant les champs et les arbres. Elles sont transportées en nuages par le vent qui vient d'Arabie en Palestine, puis s'en vont vers le nord, et périssent dans la mer. Les Orientaux les consomment, rôties, assaisonnées de sel, et les Israélites étaient autorisés à les manger.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκρίς</b> <b>ίδος (ἡ)</b> <font color=\"brown\">[ῐδ]</font> sauterelle, IL. <i>21, 12 ;</i> AR. <i>Ach. 1116 ;</i> THCR. <i>Idyl. 7, 41 ;</i> NT. <i>Matth. 3, 4 ; Marc. 1, 6, etc</i>.<b>ἄκρις</b> <b>ιος (ἡ) :<br> 1</b> sommet d’une montagne, <i>plur</i>. OD. <i>9, 400, etc. ;</i> HH. <i>Cer. 382 ;</i><br><b> 2</b> <i>p. suite,</i> région montagneuse, OD. <i>10, 281</i>.<p><b>Étym</b>. <i>cf</i>. ἄκρος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακρις - ἀκρίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G201":"<h1>akroaterion</h1>\n<p>Strong n° 201 <i>Prononciation [ak-ro-at-ay'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lieu préposé à l'écoute et aux décisions à propos de litiges, salle d'audience</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκροατήριον</b> <b>ου (τὸ)</b> <font color=\"brown\">[ᾱτ]</font> :<br><b> 1</b> salle d’audition, PLUT. <i>M. 45</i> f ; <i>particul</i>. salle d’audience d’un tribunal, NT. <i>Ap. 25, 23 ;</i><br><b> 2</b> auditoire, PLUT. <i>Cato ma. 22</i>.<p><b>Étym</b>. ἀκροάομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακροατηριον - ἀκροατήριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G202":"<h1>akroates</h1>\n<p>Strong n° 202 <i>Prononciation [ak-ro-at-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un auditeur, celui qui écoute</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκροατής</b> <b>οῦ (ὁ)</b> <font color=\"brown\">[ᾱτ]</font> :<br><b> 1</b> auditeur, THC. <i>3, 38 ; d’où</i> disciple, ARSTT. <i>Pol. 2, 12, etc. ;</i><br><b> 2</b> lecteur, PLUT. <i>Lys. 12, etc</i>.<p><b>Étym</b>. ἀκροάομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακροατης - ἀκροατής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Jacques (3)</li>\n</ul>\n</td></tr>\n</table>","G203":"<h1>akrobustia</h1>\n<p>Strong n° 203 <i>Prononciation [ak-rob-oos-tee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ne pas être circoncis, prépuce</li>\n<li>un Gentil, un païen, les incirconcis</li>\n<li>condition dans laquelle le désir et la corruption de la chair ne sont pas encore éteints</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκροβυστία</b> <b>ας (ἡ)</b> prépuce, SPT. <i>Gen. 17, 11 ; 34, 14 ; Judith 14, 10 ; 1 Macc. 1, 15</i>.<p><b>Étym</b>. ἀκρόϐυστος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακροβυστια - ἀκροβυστία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n20 fois dans 17 versets de 6 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (11)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (2)</li>\n</ul>\n</td></tr>\n</table>","G204":"<h1>akrogoniaios</h1>\n<p>Strong n° 204 <i>Prononciation [ak-rog-o-nee-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la pierre angulaire, pièce fondamentale placée à une extrémité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκρογωνιαῖος</b> <b>ἀκρο·γωνιαῖος, ος, ον</b>, qui est au sommet d’un angle, angulaire, SPT. <i>Esaï. 28, 16 ;</i> NT. <i>Eph. 2, 20</i>.<p><b>Étym</b>. ἄ. γωνία.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακρο-γωνιαιος - ἀκρογωνιαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G205":"<h1>akrothinion</h1>\n<p>Strong n° 205 <i>Prononciation [ak-roth-in'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sommet d'un tas, les premiers fruits\n<ol type=\"a\">\n<li>le meilleur d'un butin ou d'une récolte</li>\n</ol>\n</li>\n<li>le mot grec choisi vient de ce que la meilleure partie, le sommet du tas du butin, est offerte aux dieux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκροθίνιον</b> <b>ἀκρο·θίνιον, ου (τὸ)</b> <i>d’ord. pl</i>. ἀκροθίνια, ων (τὰ) <font color=\"brown\">[θῑ]</font> :<br><b>   I</b> prémices (<i>litt</i>. le dessus du tas) <i>particul. :</i><br><b> 1</b> les premiers fruits qu’on offre aux dieux, PLAT. <i>Leg. 946</i> b ; ATH. <i>499</i> a ; <i>adj</i>. ἀκροθίνια θύη, ESCHL. <i>Eum. 834,</i> offrande des premiers fruits ;<br><b> 2</b> les objets précieux d’un butin, HDT. <i>1, 86 ; 8, 121 ;</i> THC. <i>1, 132 ;</i> XÉN. <i>Cyr. 7, 5, 13, etc. ; avec un gén</i>. ἀκροθίνια ξένων, EUR. <i>I.T. 75,</i> les têtes des étrangers ;<br><b> 3</b> butin, <i>en gén</i>. NT. <i>Hebr. 7, 4</i>.<p><b>Étym</b>. ἄκρ. θίς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακρο-θινιον - ἀκροθίνιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G206":"<h1>akron</h1>\n<p>Strong n° 206 <i>Prononciation [ak'-ron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>les limites les plus éloignées, la fin, le plus haut, l'extrémité, la pointe, le bout, le sommet\n<ol type=\"a\">\n<li>de la terre</li>\n<li>des cieux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄκρον</b> <b>ου (τὸ)</b> <i>v</i>. ἄκρος.<br><br>\n<b>ἄκρος, </b><b>α, ον :<br>A</b> <i>adj</i>. extrême :<br><b>   I</b> (<i>lieu</i>) :<br><b>      1</b> le plus haut : ἀκροτάτῃ κορυφῇ, IL. <i>1, 499,</i> au plus haut sommet ; ἄκρη πόλις, IL. <i>6, 88, etc</i>. la partie haute de la ville, la citadelle (<i>cf</i>. ἀκρόπολις) ; ἐπ' ἄκρων ὀρέων, SOPH. <i>O.R. 1106,</i> au sommet des montagnes ;<br><b>      2</b> le plus au dehors : ἄκρη χείρ, IL. <i>5, 336,</i> l’extrémité de la main ; εἰς ἄκραν χεῖρα, EUR. <i>I.A. 951,</i> à l’extrémité de la main, <i>càd</i>. (il n’en viendra pas même) à l’effleurer du doigt ; ἄκροι πόδες, IL. <i>16, 640,</i> le bout des pieds ; ἐπ' ἄκρων (δακτύλων) SOPH. <i>Aj. 1230,</i> sur la pointe des pieds ; γλῶσσα ἄκρα, SOPH. <i>Aj. 238,</i> l’extrémité <i>ou</i> le bord de la langue ; ἄκρα τὰ ἱστία, AR. <i>Ran. 999,</i> le bord (inférieur <i>ou</i> supérieur) des voiles ;<br><b>      3</b> le plus profond : <i>fig</i>. ἄ. μυελὸς ψυχῆς, EUR. <i>Hipp. 255,</i> le plus profond de la moelle de l’âme ;<br><b>   II</b> (<i>temps</i>) ce qui arrive au moment <i>ou</i> au point culminant : ἄκρᾳ σὺν ἑσπέρᾳ, PD. <i>P. 11, 18,</i> quand le soir est entièrement venu ; ἄκρας νυκτός, SOPH. <i>Aj. 285,</i> au plus profond, au milieu de la nuit (<i>ttef. dans qqes composés</i> ἄ. <i>marque le commencement : v</i>. ἀκρόνυχος, ἀκροφανής, <i>etc</i>.) ;<br><b>   III</b> (<i>degré</i>) :<br><b>      1</b> le plus haut, supérieur, <i>en parl. de pers</i>. ἄ. μάντις, SOPH. <i>El. 1499,</i> devin supérieur dans son art ; <i>avec un acc. ou un gén</i>. ἄκροι τὰ πολέμια, HDT. <i>7, 111 (cf. 7, 5, 124</i>) supérieurs dans les choses de la guerre ; οἱ ἄ. τῆς ποιήσεως, PLAT. <i>Theæt. 152</i> e, les plus habiles en poésie ; <i>qqf. avec une prép</i>. ἄ. εἴς τι, PLAT. <i>Rsp. 499</i> c ; περί τι, PLAT. <i>Leg. 833</i> e, ἐπί τινι, EUN. <i>p. 56</i>, supérieur en qqe ch. ; <i>en parl. de choses (plaisirs,</i> PLAT. <i>Phil. 45</i> a ; <i>liberté,</i> PLAT. <i>Rsp. 564</i> a ; <i>amitié,</i> PLUT. <i>Arat. 43, etc</i>.) ;<br><b>      2</b> extrême (le plus haut <i>ou</i> le plus bas) : οἱ ἄ. ARSTT. <i>Pol. 4, 12,</i> les plus riches et les plus pauvres, les plus puissants et les plus faibles, <i>p. opp. à</i> μέσος ;<br><b>      3</b> qui parle <i>ou</i> agit exactement comme il convient, <i>d’où</i> exact, sûr : σοι μάντις εἰμὶ τῶνδ' ἄκρος, SOPH. <i>El. 1499,</i> voilà ce que je te prédis à coup sûr ;<br><b>B</b> <i>Subst. :</i><br><b>   I</b> ἡ ἄκρα ;<br><b>   II</b> τὸ ἄκρον :<br><b>      1</b> le sommet : τὰ ἄκρα, HDT. <i>6, 100 ;</i> XÉN. <i>Cyr. 3, 2, 10, etc. ; An. 5, 2, 16,</i> etc. les hauteurs ; <i>fig</i>. le rang le plus élevé : εἰς ἄκρον ἱκέσθαι, HÉS. <i>O. 286, etc., ou</i> ἐπ' ἄ. ἀφικέσθαι, PLAT. <i>Pol. 268</i> e, <i>ou</i> ἐλθεῖν, PLAT. <i>Tim. 20</i> a, être parvenu au sommet ;<br><b>      2</b> le point le plus avancé, le point extrême, l’extrémité ; <i>en parl. d’un lieu,</i> promontoire, cap, OD. <i>3, 278 ; ou</i> frontière, limite, POL. <i>1, 42, 2 ; en parl. du corps :</i> τὰ ἄκρα, les extrémités (bout des doigts, des pieds., <i>etc</i>.) LUC. <i>Im. 6 ;</i> τὰ ἄκρα τόξου, HÉRON, les extrémités d’un arc ; <i>fig. en parl. d’un raisonnement,</i> τὰ ἄ. ARSTT. les termes extrêmes (majeure, mineure) <i>p. opp. au terme moyen</i> (τὸ μέσον, <i>v</i>. μέσος) ;<br><b>   III</b> τὰ ἄκρα (<i>cf</i>. II, 2) :<br><b>      1</b> le plus haut rang, PLAT. <i>Rsp. 478</i> e ; ἄκρα φέρεσθαι, THCR. <i>Idyl. 12, 31,</i> remporter le prix ;<br><b>      2</b> <i>en parl. de pers</i>. les plus puissants : Ἄργεος ἄκρα Πελασγοί, THCR. <i>Idyl. 14, 142,</i> les Pélasges, les anciens maîtres d’Argos ;<br><b>C</b> <i>Adv</i>. ἄκρον <i>et</i> ἄκρα :<br><b>      1</b> au sommet : ἄκρον ἐπὶ ῥηγμῖνος, IL. <i>20, 229,</i> sur la crête de la vague ;<br><b>      2</b> au point extrême, à la limite, ANTH. <i>7, 428 ;</i><br><b>      3</b> au plus haut point, d’une façon supérieure, THCR. <i>Idyl. 27, 43 ;</i> ANTH. <i>7, 448</i>.<br><span>•<i> Cp</i>. -ότερος, ARR. <i>An. 5, 26, 9</i>. <i>• Sup</i>. -ότατος, IL. <i>1, 499, etc. ;</i> HÉS. <i>Th. 7 ;</i> XÉN. <i>Hell. 4, 5, 3 ;</i> PLAT. <i>Leg. 906</i> b ; LUC. <i>D. deor. 11, 2, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂eḱ-, pointu, <i>cf. lat</i>. ācer, ācris, ācre.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακρον - ἄκρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G207":"<h1>Akulas</h1>\n<p>Strong n° 207 <i>Prononciation [ak-oo'-las]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Aquilas (Angl. Aquila) = « un aigle »\n<ol><li>Juif, né dans le royaume du Pont, fabricant de tente, converti à Christ, compagnon et allié de Paul dans la propagation du christianisme. Epoux de Priscille, converti à Corinthe.</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ακυλας - Ἀκύλας</font>\n<br><br>probablement du Latin aquila (un aigle)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G208":"<h1>akuroo</h1>\n<p>Strong n° 208 <i>Prononciation [ak-oo-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rendre nul, priver de force et d'autorité, priver de valeur, annuler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκυρόω</b> <b>ἀκυρόω-ῶ</b> <font color=\"brown\">[ῡ]</font> considérer comme non avenu, annuler, DH. <i>2, 72 ;</i> DS. <i>16, 24 ;</i> PLUT. <i>Lyc. 9 ;</i> SPT. <i>3Esdr. 6, 32</i>.<p><b>Étym</b>. ἄκυρος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κυροω - ἀκυρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G209":"<h1>akolutos</h1>\n<p>Strong n° 209 <i>Prononciation [ak-o-loo'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans empêchement, librement, sans obstacle, non empêché, libre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκωλύτως</b> <font color=\"brown\">[ῡ]</font> <i>adv</i>. sans empêchement, PLAT. <i>Crat. 415</i> d.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κωλυτως - ἀκωλύτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G210":"<h1>akon</h1>\n<p>Strong n° 210 <i>Prononciation [ak'-ohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non de sa propre volonté, contre la volonté, qui ne consent pas, qui n'est pas d'accord</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄκων ²</b> <b>ουσα, ον</b>, <i>gén</i>. <b>οντος, ούσης, οντος</b> <font color=\"brown\">[ᾰ]</font> (<i>contr. p</i>. ἀέκων) <i>propr</i>. qui ne veut pas, <i>d’où :</i><br><b>   I</b> <i>en parl. de pers. :</i><br><b> 1</b> qui refuse, qui ne consent pas : ἄκοντος Διός, ESCHL. <i>Pr. 771,</i> malgré Zeus ;<br><b> 2</b> que l’on contraint, <i>d’où</i> qui agit malgré soi, contraint, forcé, ESCHL. <i>Pr. 19, Suppl. 234 ; p. opp. à</i> θέλουσα, ESCHL. <i>Sept. 1013 ;</i> ἐάντε ἑκόντας ἐάντε ἄκοντας, PLAT. <i>Pol. 293</i> b : ἑκοῦσί τε καὶ ἄκουσιν, PLAT. <i>Phil. 14</i> c ; καὶ ἑκὼν καὶ ἄκων, ARSTD. <i>25, 311,</i> bon gré, mal gré (<i>litt</i>. lui <i>ou</i> eux voulant bien ou ne voulant pas) ;<br><b> 3</b> qui fait qqe ch. involontairement, par mégarde, PLUT. <i>M. 233</i> f ;<br><b>   II</b> <i>en parl. de choses,</i> involontaire, SOPH. <i>O.R. 1230, O.C. 240</i>.<p><b>➼</b> <i>Poét</i>. ἀέκων, IL. <i>1, 310, etc. (dans Hom. touj</i>. ἀέκων, <i>sauf au duel</i> ἄκοντε, IL. <i>5, 366 ;</i> OD. <i>3, 484</i>) ESCHL. <i>Suppl. 40, etc. ;</i> ἀέκων <i>conservé dans le dialecte att. j. au 5<sup>e</sup> siècle av. J.C. dans un fragment des lois de Dracon,</i> CIA. <i>1, 61, 34 (409 av. J.C</i>.); <i>ttef. v</i>. ἀκούσιος (<i>v. Meisterh. p. 57, § 26, 2</i>).</p><p><b>Étym</b>. ἀ, ἑκών.</p><b>ἄκων ¹</b> <b>οντος (ὁ)</b> <font color=\"brown\">[ᾰ]</font> javelot, IL. <i>15, 709 ;</i> OD. <i>14, 531 ;</i> PD. <i>P. 9, 37 ; rare chez les Trag</i>. EUR. <i>Ph. 1402, Rhes. 370 ; fig</i>. PD. <i>P. 1, 84 ; O. 13, 133</i>.<p><b>Étym</b>. <i>R. indo-europ</i>. *h₂eḱ-, pointu ; <i>cf</i>. ἀκή.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακων - ἄκων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G211":"<h1>alabastron</h1>\n<p>Strong n° 211 <i>Prononciation [al-ab'-as-tron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un pot fait d'albâtre, dans lequel on conservait parfums et onguents</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλάβαστρον</b> <b>ου (τὸ)</b> <i>c</i>. ἀλάϐαστρος NT. <i>Marc. 14, 3 ; plur</i>. THCR. <i>Idyl. 15, 114 ;</i> ANTH. <i>9, 153</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλαβαστρον - ἀλάβαστρον</font>\n<br><br>vient de alabastros (dérivation incertaine, nom d'une pierre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G212":"<h1>alazoneia</h1>\n<p>Strong n° 212 <i>Prononciation [al-ad-zon-i'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vide, parole de fanfaron, vantardise, satisfaction insolente</li>\n<li>assurance insolente, qui croit dans sa propre puissance, et viole les lois divines et les droits humains</li>\n<li>présomption impie qui croit dans la stabilité des choses de la terre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλαζονεία</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾰᾱζ]</font> jactance, vantardise, PLAT. <i>Gorg. 523</i> a ; <i>Hipp. mi. 371</i> a ; ARSTT. <i>Rhet. 1, 6 ; Nic. 4, 7 ;</i> TH. <i>Char. 23 ; joint à</i> κόμπως, ESCHN. <i>632 ; à</i> ὕϐρις, PLAT. <i>Phædr. 253</i> e ; EL. <i>V.H. 2, 15 ; à</i> ψεῦδος, PLAT. <i>Gorg. 525</i> a ; <i>à</i> οἴημα, PLUT. <i>M. 43</i> b ; <i>au plur</i>. AR. <i>Eq. 290 ;</i> ISOCR. <i>237</i> b ; fanfaronnades, hâbleries ; <i>p. anal</i>. ἀ. τῶν χορδῶν, PLAT. <i>Rsp. 531</i> b, cordes aux sons faux et criards.<p><b>Étym</b>. ἀλαζών.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλαζονεια - ἀλαζονεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G213":"<h1>alazon</h1>\n<p>Strong n° 213 <i>Prononciation [al-ad-zone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un prétendant vide, un vantard, fanfaron, charlatan</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλαζών</b> <b>όνος (ὁ, ἡ)</b> <font color=\"brown\">[ᾰᾱ]</font> :<br><b>   I</b> <i>propr</i>. vagabond, ALC. COM. <i>2, 833 ;</i><br><b>   II</b> <i>p. suite :</i><br><b> 1</b> charlatan, imposteur, PLAT. <i>Eryx. 399</i> c, <i>Rsp. 486</i> b, <i>etc. ; en parl. de choses (promesses, paroles, etc</i>.) PLAT. <i>Phæd. 92</i> d ; <i>joint à</i> ψευδής, PLAT. <i>Rsp. 560</i> c ; <i>à</i> κενός, PLUT. <i>M. 81</i> b ;<br><b> 2</b> glorieux, vantard, fanfaron, <i>en parl. de pers</i>. XÉN. <i>Cyr. 2, 2, 5 ;</i> AR. <i>Ach. 109 ;</i> ARSTT. <i>Nic. 4, 7, 11, etc</i>.<br><i>● Sup</i>. -ονέστατος, PLAT. <i>Phil. 65</i> c ; EL. <i>N.A. 4, 29</i>.<p><b>Étym</b>. ἀλάομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλαζων - ἀλαζών</font>\n<br><br>vient de ale (vagabondage)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G214":"<h1>alalazo</h1>\n<p>Strong n° 214 <i>Prononciation [al-al-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>répéter fréquemment le cri « alala » était une coutume des soldats entrant dans la bataille, lancer un son rituel</li>\n<li>pousser un cri de joie</li>\n<li>gémir, se lamenter</li>\n<li>sonner fortement, résonner Pour les Synonymes</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλαλάζω</b> <font color=\"darkgreen\">(<i>impf</i>. ἠλάλαζον, <i>f</i>. ἀλαλάξομαι, <i>ao</i>. ἠλάλαξα, <i>pf. inus</i>.)</font> <font color=\"brown\">[ᾰλᾰλ]</font> :<br><b>   I <i>intr</i>.<br> 1</b> pousser le cri de guerre en marchant à l’ennemi, XÉN. <i>An. 6, 5, 27, etc. ;</i> ἀλ. τῷ Ἐνυαλίῳ, XÉN. <i>An. 5, 2, 14 dout</i>. pousser le cri de guerre en l’honneur d’Ényalios ;<br><b> 2</b> pousser un grand cri, <i>en gén</i>. PD. <i>O. 7, 37 ; en parl. d’un cri de joie,</i> EUR. <i>El. 855 ; de douleur, d’angoisse, de frayeur,</i> EUR. <i>El. 843 ;</i> PLUT. <i>Luc. 28 ;</i> NT. <i>Marc. 5, 38 ;</i> NONN. <i>D. 70, 6, etc. ;</i><br><b> 3</b> <i>en parl. d’instruments,</i> retentir, ESCHL. <i>fr. 55 ;</i> NT. <i>1Cor. 13, 1 ;</i><br><b>   II <i>tr</i></b>. annoncer avec des cris de joie, proclamer : νίκην, SOPH. <i>Ant. 133,</i> une victoire ;<br><b><i>Moy</i></b>. pousser le cri de guerre, ARR. <i>An. 5, 10, 3</i>.<p><b>➼</b> <i>Impf. poét</i>. ἀλάλαζον, NONN. <i>D. 1, 242 ; fut</i>. ἀλαλάξομαι, EUR. <i>Bacch. 593 ; postér</i>. ἀλαλάξω, SPT. <i>Jer. 29, 3, etc. Ao. 3 sg. poét</i>. ἀλάλαξεν <font color=\"brown\">[ᾰλᾰλ]</font> PD. <i>O. 7, 37 ; pour l’ao</i>. ἠλάλαξαν, <i>dans</i> XÉN. <i>An. 5, 2, 14, Dind. et Cobet lisent</i> ἠλέλιξαν.</p><p><b>Étym</b>. ἀλαλή.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλαλζω - ἀλαλάζω</font>\n<br><br>vient de alale (un cri, « Allo ! »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – gémir, dans un style oriental, hurler d'une façon semi liturgique\n<br><br> – verser des larmes, pleurer silencieusement\n<br><br> – pleurer en y mettant certaines formes, exprimer un grief, chanter un chant funèbre\n<br><br> – pleurer avec cris, pleurer comme un enfant\n<br><br> – exprimer verbalement un grief, se lamenter\n<br><br> – exprimer un grief par des sons inarticulés, ou semi-articulés, gémir</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G215":"<h1>alaletos</h1>\n<p>Strong n° 215 <i>Prononciation [al-al'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ne peut être extériorisé, ne peut s'exprimer par des mots, indescriptible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλαλητός</b> <b>οῦ (ὁ)</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b>   I</b> cri :<br><b> 1</b> cri de guerre, HÉS. <i>Th. 686 ; particul</i>. cri de victoire, IL. <i>16, 78 ;</i><br><b> 2</b> cri de douleur, IL. <i>21, 10 ;</i><br><b> 3</b> grand cri, <i>en gén</i>. IL. <i>2, 149 ;</i><br><b>   II</b> grand bruit, TÉLÉCL. (ATH. <i>268</i> c).<p><b>➼</b> <i>Dor</i>. ἀλαλατός <font color=\"brown\">[ᾰᾰᾱ]</font> PD. <i>P. 1, 72</i>.</p><p><b>Étym</b>. ἀλαλάζω.</p><b>ἀλάλητος</b> <b>ἀ·λάλητος, ος, ον</b> <font color=\"brown\">[ᾰᾰ]</font> indicible, ANTH. <i>2, 4 ;</i> NT. <i>Rom. 8, 26</i>.<p><b>Étym</b>. ἀ, λαλέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-λαλητος - ἀλάλητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G216":"<h1>alalos</h1>\n<p>Strong n° 216 <i>Prononciation [al'-al-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans paroles, muet, à qui manque la faculté de parole</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄλαλος</b> <b>ἄ·λαλος, ος, ον</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b> 1</b> qui ne parle pas, muet, ESCHL. <i>fr. 57 ;</i> PLUT. <i>M. 438</i> b ; SPT. <i>Ps. 37, 13 ; joint à</i> κωφός, A. APHR. <i>Probl. 1, 138 ;</i><br><b> 2</b> qui rend muet, <i>joint à</i> κωφός, NT. <i>Marc. 9, 17</i>.<p><b>Étym</b>. ἀ, λαλέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-λαλος - ἄλαλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Marc (3)</li>\n</ul>\n</td></tr>\n</table>","G217":"<h1>halas</h1>\n<p>Strong n° 217 <i>Prononciation [hal'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sel qui sert à assaisonner les aliments et à mettre sur les offrandes</li>\n<li>produits salins utilisés pour fertiliser les terres arables</li>\n<li>symbole de la concorde, il protège la nourriture de la putréfaction, et la conserve. A cause de ceci, les orientaux ont encore la coutume de partager le sel lors de la ratification d'accords</li>\n<li>sagesse et grâce exprimées dans des paroles</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἅλας</b> <b>ατος (τὸ)</b> <font color=\"brown\">[ᾰᾰ]</font> sel, ARSTT. <i>Mir. 138 ;</i> THCR. <i>Idyl. 15, 17 ;</i> PLUT. <i>M. 668</i> f ; NT. <i>Matth. 5, 13</i>.<p><b>Étym</b>. ἅλς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλας - ἅλας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n<li>Luc (2)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G218":"<h1>aleipho</h1>\n<p>Strong n° 218 <i>Prononciation [al-i'-fo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>oindre, parfumer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλείφω</b> <font color=\"darkgreen\">(<i>f</i>. ἀλείψω ; <i>ao</i>. ἤλειψα, <i>pf</i>. ἀλήλιφα <font color=\"brown\">[ῐ]</font>; <i>pass. ao</i>. ἠλείφθην, <i>pf</i>. ἀλήλιμμαι)</font> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> graisser, oindre, <i>particul. en parl. d’athlètes :</i> ἀ. ἐλαίῳ, IL. <i>18, 350, ou abs</i>. ἀλείφειν, IL. <i>24, 582 ;</i> OD. <i>6, 227,</i> oindre d’huile, frotter d’huile ; <i>p. suite,</i> préparer à la lutte, <i>d’où</i> exciter, encourager, DÉMAD. <i>180, 29 ;</i> PLAT. (DL. <i>4, 6</i>); τινὰ ἐπί τινα, APP. <i>Civ. 2, 16,</i> exciter qqn contre qqn ; <i>p. anal</i>. préparer, <i>en gén.:</i> ἀ. ἑαυτὸν ἐπί τι, PLUT. <i>Them. 3,</i> se préparer à qqe ch. (à une lutte, <i>etc</i>.) ;<br><b> 2</b> enduire, <i>en gén</i>. (de cire, de fard, <i>etc</i>.) OD. <i>12, 47 ;</i> HDT. <i>3, 8 ;</i> XÉN. <i>Œc. 10, 5 ;</i> PLAT. <i>Lys. 217</i> d ;<br><b><i>Moy</i></b>. <font color=\"darkgreen\">(<i>f</i>. ἀλείψομαι, <i>ao</i>. ἠλειψάμην)</font> s’enduire soi-même, IL. <i>10, 577, etc. ;</i> THC. <i>1, 6 ; 4, 68</i>.<p><b>➼</b> <i>Formes poét. ou rares : Impf. 3 sg. poét</i>. ἄλειφε, OD. <i>10, 392. Ao. poét</i>. ἄλειψα, OD. <i>12, 177. Pass. ao.2</i> ἠλίφην, JOS. <i>B.J. 2, 8, 3. Pf. réc</i>. ἤλειμμαι, GEOP. <i>7, 8, 9. Moy. ao. poét</i>. ἀλειψάμην, IL. <i>14, 171</i>.</p><p><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *h₂leib<sup>h</sup>-, onguent, <i>cf</i>. ἀλίνω, <i>lat</i>. linō <i>ou p.-ê. pré-grec ; non apparenté à</i> λίπα.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλειφω - ἀλείφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – est le mot commun, mondain, pour parfumer, oindre, parfumer\n<br><br> – est le mot religieux et sacré pour oindre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G219":"<h1>alektorophonia</h1>\n<p>Strong n° 219 <i>Prononciation [al-ek-tor-of-o-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le cri du coq, le chant du coq\n<ol type=\"a\">\n<li>utilisé pour la troisième veille de la nuit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλεκτοροφωνία</b> <b>ἀλεκτορο·φωνία, ας (ἡ)</b> <font color=\"brown\">[ᾰλ]</font> chant du coq, ES. <i>44 de Furia ;</i> NT. <i>Marc. 13, 35</i>.<p><b>Étym</b>. ἀ. φωνή.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλεκρο-φωνια - ἀλεκτοροφωνία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G220":"<h1>alektor</h1>\n<p>Strong n° 220 <i>Prononciation [al-ek'-tore]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un coq, ou mâle de n'importe quel oiseau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλέκτωρ ²</b> <b>ἀ·λέκτωρ, ορος (ὁ, ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> (ἀ <i>priv</i>.) vierge, ATH. <i>98</i> b ;<br><b> 2</b> (ἀ <i>cop</i>.) épouse, SOPH. <i>fr. 230</i>.<p><b>Étym</b>. ἀ, λέκτρον.</p><b>ἀλέκτωρ ¹</b> <b>ορος (ὁ)</b> <font color=\"brown\">[ᾰ]</font> coq, BATR. <i>191 ;</i> PD. <i>O. 12, 20 ;</i> ESCHL. <i>Ag. 1671, Eum. 861 ;</i> AR. <i>Nub. 666 ;</i> ARSTT. <i>fr. 271 ;</i> THCR. <i>Idyl. 7, 123, etc</i>.<p><b>Étym</b>. <i>cf</i>. ἀλεκτρυών.</p><b>Ἀλέκτωρ</b> <b>ορος (ὁ)</b> <font color=\"brown\">[ᾰ]</font> Alektôr, <i>h</i>. OD. <i>4, 10, etc</i>.<p><b>Étym</b>. <i>v</i>. ἀλέκτωρ¹.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλεκτωρ - ἀλέκτωρ</font>\n<br><br>vient de parer</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (4)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G221":"<h1>Alexandreus</h1>\n<p>Strong n° 221 <i>Prononciation [al-ex-and-reuce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>natif ou résident à Alexandrie en Egypte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αλεξανδρευς - Ἀλεξανδρεύς</font>\n<br><br>vient de la ville ainsi nommée</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nom masculin</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G222":"<h1>Alexandrinos</h1>\n<p>Strong n° 222 <i>Prononciation [al-ex-an-dree'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>natif ou résident d'Alexandrie en Egypte</li>\n<li>qui vient ou provient d'Alexandrie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀλεξανδρῖνος</b> <b>η, ον</b>, d’Alexandrie, Alexandrin, STR. <i>599 ;</i> NT. <i>Ap. 27, 6, etc</i>.<p><b>Étym</b>. Ἀλεξάνδρεια.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αλεξανδρινος - Ἀλεξανδρίνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G223":"<h1>Alexandros</h1>\n<p>Strong n° 223 <i>Prononciation [al-ex'-an-dros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Alexandre (Angl. Alexander) = « défenseur des hommes »\n<ol>\n<li>fils de Simon de Cyrène qui porta la croix de Jésus (<a class=\"ref\" data-r=\"MRK15.21\">Mr 15.21</a>)</li>\n<li>un homme de la parenté du souverain sacrificateur (<a class=\"ref\" data-r=\"ACT4.6\">Ac 4.6</a>)</li>\n<li>un certain Juif (<a class=\"ref\" data-r=\"ACT19.33\">Ac 19.33</a>)</li>\n<li>un forgeron opposé à l'Apôtre Paul (<a class=\"ref\" data-r=\"1TI1.20\">1Ti 1.20</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλέξανδρος</b> <b>ἀλέξ·ανδρος, ος, ον</b>, qui protège les hommes, INSCR. (DS. <i>11, 14</i>).<p><b>Étym</b>. ἀλέξω, ἀνήρ.</p><b>Ἀλέξανδρος</b> <b>Ἀλέξ·ανδρος, ου (ὁ)</b> Alexandre :<br><b> 1</b> <i>autre n. de Pâris, fils de Priam,</i> IL. <i>3, 16, etc. ;</i> HDT. <i>1, 3 ;</i> XÉN. <i>Conv. 4, 20, etc. ;</i><br><b> 2</b> <i>n. de divers rois de Macédoine,</i> HDT. <i>5, 19 ;</i> THC. <i>1, 57 ; etc. ; particul. Alexandre le Grand, fils de Philippe,</i> PLUT. <i>Æmil. 23, Pel. 34, etc. ;</i><br><b> 3</b> <i>autres,</i> PLUT. <i>Phoc. 33, Pyrrh. 6, etc</i>.<p><b>Étym</b>. <i>v</i>. ἀλέξανδρος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αλεξανδρος - Ἀλέξανδρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (3)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G224":"<h1>aleuron</h1>\n<p>Strong n° 224 <i>Prononciation [al'-yoo-ron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>farine de blé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄλευρον</b> <b>ου (τὸ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> farine de froment, <i>d’ord. au pl., p. opp. à</i> ἄλφιτα, HDT. <i>7, 119 ;</i> XÉN. <i>An. 1, 5, 6 ;</i> PLAT. <i>Rsp. 372</i> b, <i>etc. ; au sg</i>. AR. <i>fr. 141 ;</i> ARSTT. <i>Probl. 21, 1 ;</i><br><b> 2</b> farine, <i>en gén</i>. DIOSC. <i>1, 94, etc</i>.<p><b>Étym</b>. ἀλέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλευρον - ἄλευρον</font>\n<br><br>vient de aleo (moudre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT).\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G225":"<h1>aletheia</h1>\n<p>Strong n° 225 <i>Prononciation [al-ay'-thi-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>objectivement\n<ol type=\"a\">\n<li>ce qui est vrai quelle que soit la considération</li>\n<li>ce qui est vrai dans ce qui appartient à Dieu et aux devoirs de l'homme, vérité morale et religieuse</li>\n<li>la vérité enseignée dans la religion chrétienne, appuyée sur Dieu et l'exécution de ses desseins à travers Christ, dictant les devoirs de l'homme, rejetant les superstitions des païens et les inventions des Juifs, et les opinions corrompues des faux enseignants pouvant se trouver parmi les Chrétiens</li>\n</ol>\n</li>\n<li>subjectivement,\n<ol type=\"a\">\n<li>vérité en tant qu'excellence personnelle\n<ol>\n<li>candeur d'esprit, libre d'affection, de prétention, de simulation, de mensonge, de tromperie</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλήθεια</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾰλ]</font> :<br><b>   I</b> vérité :<br><b> 1</b> <i>p. opp. à l’erreur ou au mensonge :</i> ἀληθείην καταλέξαι, IL. <i>24, 407 ;</i> ἀποειπεῖν, IL. <i>23, 361 ;</i> εἶπαι τὴν ἀληθείην, HDT. <i>6, 69,</i> dire la vérité ; πᾶσαν ἀ. μυθεῖσθαι, OD. <i>11, 507, ou</i> πᾶσαν τὴν ἀ. εἰπεῖν, ATT. dire toute la vérité ; <i>au plur</i>. τὰς ἀληθείας λέγειν, MÉN. (<i>Bkk. 376), ou</i> ταῖς ἀληθείαις χρῆσθαι, ISOCR. <i>190</i> a, <i>m. sign. ;</i> ἀλήθειαν ἔχειν, ARSTT. <i>Pol. 3, 11, 1,</i> être vrai ;<br><b> 2</b> <i>p. suite,</i> habitude de dire la vérité, sincérité, franchise, HDT. <i>1, 55 ;</i> ESCHL. <i>Ag. 1550 ;</i> ARSTT. <i>Nic. 2, 7, 12, etc. ;</i><br><b>   II</b> réalité, <i>p. opp. à</i> faux-semblant, apparence, THC. <i>2, 41 ;</i> PLAT. <i>Pol. 300</i> d ; ἐρυθροτέρα τῆς ἀληθείας, XÉN. <i>Œc. 10, 2</i> (femme) plus rouge (à cause du fard) qu’elle n’est en réalité ; τῇ ἀληθείᾳ, THC. <i>4, 120 ;</i> ἀληθείᾳ, PLAT. <i>Prot. 338</i> c, <i>Phædr. 277</i> e, <i>etc. ;</i> ἀπ' ἀληθείας, DÉM. <i>323, 26 ;</i> μετ' ἀληθείας, XÉN. <i>Mem. 2, 1, 27 ;</i> DÉM. <i>19, 1 ;</i> μετὰ πάσης ἀληθείας, DH. <i>Pomp. 6 ;</i> PLUT. <i>M. 341</i> c ; κατὰ τὴν ἀλήθειαν, ISOCR. <i>242</i> a ; κατ' ἀλήθειαν, ARSTT. <i>Pol. 3, 6, 6 ;</i> ξὺν ἀληθείᾳ, ESCHL. <i>Ag. 1567 ;</i> πρὸς ἀλήθειαν, DS. <i>5, 67, etc. ;</i> πρὸς τὴν ἀλήθειαν, POL. <i>10, 21, 10, etc</i>. en réalité, en vérité, en toute vérité ; <i>p. suite,</i> réalisation, accomplissement d’un songe, d’un oracle, HDT. <i>3, 64 ;</i><br><b>   III</b> symbole de vérité, ornement en saphir que portait le grand-prêtre égyptien, DS. <i>1, 48 et 75 ;</i> EL. <i>V.H. 13, 34</i>.<p><b>➼</b> <i>Épq. et ion</i>. ἀληθείη, IL. <i>23, 361, etc. ;</i> OD. <i>11, 507 ; dor</i>. ἀλάθεια, ESCHL. <i>Ag. 1550, etc. ou</i> ἀλάθεα <font color=\"brown\">[λᾱ]</font> THCR. <i>Idyl. 29, 1</i>.</p><p><b>Étym</b>. ἀληθής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αληθεια - ἀλήθεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n109 fois dans 98 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (3)</li>\n<li>Luc (3)</li>\n<li>Jean (25)</li>\n<li>Actes (3)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (8)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (6)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>1 Timothée (6)</li>\n<li>2 Timothée (6)</li>\n<li>Tite (2)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (9)</li>\n<li>2 Jean (5)</li>\n<li>3 Jean (6)</li>\n</ul>\n</td></tr>\n</table>","G226":"<h1>aletheuo</h1>\n<p>Strong n° 226 <i>Prononciation [al-ayth-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dire ou enseigner, professer la vérité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀληθεύω</b> <font color=\"darkgreen\">(<i>f</i>. εύσω, <i>ao</i>. ἠλήθευσα, <i>pf</i>. ἠλήθευκα)</font> <font color=\"brown\">[ᾰ]</font> :<br><b>   I <i>tr</i>.<br> 1</b> <i>abs</i>. dire la vérité, HPC. <i>Progn. 42 ;</i> PLAT. <i>Rsp. 589</i> c, <i>etc. ; avec un adj. neutre :</i> ἀ. πάντα, BATR. <i>14,</i> dire toute la vérité ; <i>au pass</i>. être dit selon la vérité, être conforme à la vérité, ARSTT. <i>Metaph. 3, 5, 2 ;</i><br><b> 2</b> déclarer franchement : τι, XÉN. <i>An. 5, 6, 18,</i> qqe ch. ;<br><b> 3</b> affirmer <i>ou</i> prouver la vérité de : τι, LUC. <i>Ind. 20,</i> de qqe ch. ;<br><b> 4</b> rendre réel, réaliser : τὰς ὑποσχέσεις, DH. <i>3, 24,</i> tenir ses promesses ;<br><b>   II <i>intr</i>.<br> 1</b> être vrai, HPC. <i>46, 48 ;</i> PAUS. <i>6, 12, 3, etc. ;</i><br><b> 2</b> parvenir à la vérité, ARSTT. <i>Metaph. 3, 5, 2 ;</i><br><b><i>Moy</i></b>. dire la vérité, XÉN. <i>Cyr. 4, 6, 10</i>.<p><b>➼</b> <i>Ao</i>. ἠλήθευσα, XÉN. <i>An. 5, 6, 18 ; pf</i>. ἠλήθευκα, ARSTT. <i>Interpr. 10, 14. Fut. moy. au sens pass</i>. ARSTT. <i>Nic. 1, 11, 37, etc</i>.</p><p><b>Étym</b>. ἀληθής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλητευω - ἀληθεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G227":"<h1>alethes</h1>\n<p>Strong n° 227 <i>Prononciation [al-ay-thace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vrai, réel authentique</li>\n<li>amour de la vérité, parler avec vérité, sincère</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀληθής</b> <b>ἀ·ληθής, ής, ές</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> <i>intr</i>. non caché, <i>d’où</i> vrai :<br><b> 1</b> vrai, sincère, franc, <i>p. opp. à</i> faux, <i>en parl. de pers</i>. ESCHL. <i>Sept. 439 ;</i> THC. <i>3, 56 ;</i><br><b> 2</b> loyal, juste, équitable, IL. <i>12, 433, etc. ;</i><br><b> 3</b> <i>en parl. de choses (oracles, songes, etc</i>.) véridique, ESCHL. <i>Sept. 692 ;</i> SOPH. <i>Ph. 993 ;</i> EUR. <i>Ion 1537 ; p. opp. à</i> ψευδῆ, EUR. <i>I.A. 957 ;</i> ἀληθέα εἰπεῖν, μυθήσασθαι, <i>etc</i>. IL. <i>6, 382, etc. ;</i> ἀληθέϊ λόγῳ χρῆσθαι, HDT. <i>1, 14,</i> dire la vérité, parler franchement ; καὶ τοῦτ' ἄρ' ἦν ἀληθές, EUR. <i>I.T. 351,</i> il est donc vrai ; τὸ ἀληθές, HDT. <i>7, 139,</i> τἀληθές, SOPH. <i>El. 679 ; Tr. 453, 474 ; O.R. 944, etc. ;</i> τὠληθές, HDT. <i>6, 68, 69 ;</i> τὰ ἀληθῆ, <i>d’où</i> τἀληθῆ, PLAT. <i>Prot. 323</i> b, <i>etc</i>. la vérité ;<br><b> 4</b> <i>adv. dans les réponses :</i> ἀληθῆ, PLAT. <i>Theæt. 143</i> a, <i>etc</i>. exactement, justement ;<br><b> 5</b> véritable, réel (<i>p. opp. à</i> apparent <i>ou à</i> vain) : φίλος ἀ. EUR. <i>Or. 424,</i> véritable ami ; <i>adv</i>. τὸ ἀληθές, PLAT. <i>Phæd. 102</i> b, véritablement, en réalité ; <i>mais (avec changem. d’accent) dans les interr</i>. ἄληθες ; vraiment ? en vérité ? réellement ? SOPH. <i>O.R. 350, Ant. 758 ;</i> AR. <i>Ran. 840, etc. ; p. suite,</i> qui se réalise : ἀρὰ ἀ. ESCHL. <i>Sept. 946,</i> malédiction qui s’accomplit ;<br><b>   II</b> <i>tr</i>. qui rend franc : οἶνος ἀ. ἔστι, PLAT. <i>Conv. 217</i> e, le vin provoque la franchise ; <i>cf</i>. ARSTT. <i>Nic. 4, 7</i>.<br><i>● Cp</i>. -έστερος, XÉN. <i>Œc. 16, 4 ;</i> PLAT. <i>Rsp. 585</i> b, <i>etc.</i> <i>● Sup</i>. -έστατος, THC. <i>1, 23, etc. ;</i> PLAT. <i>Phæd. 65</i> e, <i>etc</i>.<p><b>➼</b> <i>Dor</i>. ἀλαθής <font color=\"brown\">[ᾰᾱ]</font> PD. <i>O. 2, 92, etc</i>.</p><p><b>Étym</b>. ἀ, λαθεῖν.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλητης - ἀληθής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n25 fois dans 25 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (13)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (2)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G228":"<h1>alethinos</h1>\n<p>Strong n° 228 <i>Prononciation [al-ay-thee-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui n'a pas seulement le nom et la ressemblance, mais qui a la réelle nature correspondant au nom, dans le respect de l'idée signifiée par le nom, le réel, le vrai, le véritable, le véridique, franc, loyal, sûr\n<ol type=\"a\">\n<li>opposé à ce qui est factieux, contrefait, imaginaire, simulé ou prétendu</li>\n<li>les contrastes entre la vérité et ses ressemblances</li>\n<li>opposé à ce qui est imparfait, défectueux, fragile, incertain</li>\n</ol>\n</li>\n<li>vrai, sincère</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀληθινός</b> <b>ή, όν</b> <font color=\"brown\">[ᾰῐ]</font> :<br><b> 1</b> véridique, sincère, XÉN. <i>An. 1, 9, 17 ;</i> PLUT. <i>M. 184</i> c ;<br><b> 2</b> vrai, réel, PLAT. <i>Rsp. 499</i> c ; ARSTT. <i>Pol. 3, 11, 4</i>.<br><i>● Cp</i>. -ώτερος. PLAT. <i>Rsp. 522</i> a ; DH. <i>Isocr. 20</i>. <i>● Sup</i>. -ώτατος, PLAT. <i>Pol. 296</i> e ; POL. <i>1, 1, 2, etc</i>.<p><b>➼</b> <i>Dor</i>. ἀλαθινός <font color=\"brown\">[λᾱ]</font> THCR. <i>Idyl. 13, 15 ; 17, 3</i>.</p><p><b>Étym</b>. ἀληθής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αληθινος - ἀληθινός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 25 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (8)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (3)</li>\n<li>1 Jean (4)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G229":"<h1>aletho</h1>\n<p>Strong n° 229 <i>Prononciation [al-ay'-tho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>moudre, travailler à moudre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλήθω</b> (<i>seul. prés</i>. TH. <i>C.P. 4, 12, 13 ;</i> ANTH. <i>11, 154, et impf</i>. ἤληθον, BABR. <i>131, 5 ;</i> NT. <i>Matth. 24, 41</i>) moudre.<p><b>Étym</b>. ἀλέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αληθω - ἀλήθω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT).\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G230":"<h1>alethos</h1>\n<p>Strong n° 230 <i>Prononciation [al-ay-thoce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vraiment, en vérité, en réalité, très certainement, véritablement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀληθῶς</b> <font color=\"brown\">[ᾰ]</font> <i>adv. :</i><br><b> 1</b> véritablement, sincèrement, HDT. <i>1, 11 ;</i> ESCHL. <i>Suppl. 310, etc. ;</i><br><b> 2</b> réellement, ESCHL. <i>Suppl. 585, etc. ;</i> THC. <i>1, 22 ; souv. enclavé entre l’art. et le nom, et d’ord., en ce cas, précédé de</i> ὡς : οἱ ὡς ἀ. φιλόσοφοι, PLAT. <i>Phædr. 64</i> b, les vrais philosophes ; <i>qqf. sans</i> ὡς, ANTIPH. (ATH. <i>643</i> e).<br><i>● Cp</i>. ἀληθέστερον, THC. <i>1, 69, etc. ; ou</i> -τέρως, PLAT. <i>Rsp. 347</i> e, <i>etc.</i> <i>● Sup</i>. ἀληθέστατα, XÉN. <i>Mem. 4, 8, 1 ;</i> PLAT. <i>Rsp. 349</i> a, <i>Phædr. 266</i> b, <i>etc</i>.<p><b>➼</b> <i>Ion</i>. ἀληθέως, HDT. <i>1, 11. Dor</i>. ἀλαθέως <font color=\"brown\">[λᾱ]</font> SIM. (DL. <i>1, 76), etc</i>.</p><p><b>Étym</b>. ἀληθής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αληθως - ἀληθῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 19 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (10)</li>\n<li>Actes (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G231":"<h1>halieus</h1>\n<p>Strong n° 231 <i>Prononciation [hal-ee-yoos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un pêcheur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁλιεύς</b> <b>έως (ὁ)</b> <font color=\"brown\">[ᾰ]</font> qui vit sur mer, <i>d’où :</i><br><b>   I</b> <i>subst. :</i><br><b> 1</b> pêcheur, OD. <i>12, 251 ; 22, 384 ;</i> HDT. <i>3, 42 ;</i> SOPH. <i>fr. 118 ;</i> PLAT. <i>Ion 539</i> e, <i>etc. ;</i><br><b> 2</b> marin, matelot, OD. <i>24, 419 ;</i><br><b> 3</b> sorte de poisson, PLUT. <i>M. 978</i> d ;<br><b>   II</b> <i>adj</i>. ἐρέται ἁλ. OD. <i>16, 349,</i> rameurs sur mer ; βάτραχος ἁλ. grenouille de mer (<i>lophius piscatorius</i> L.) ARSTT. <i>H.A. 9, 37</i>.<p><b>➼</b> <i>Voc</i>. -εῦ, CLÉM. <i>Hymn. p. 312 ; gén. contr</i>. -ιῶς, PHÉRÉCR. (<i>Bkk. 383) ; acc. pl. non contr</i>. ἁλιέας, ANTIPH. (<i>Com. fr. 3, 104, 17</i>); ALEX. (<i>Com. fr. 3, 455). Décl. épq. et ion. : pl. nom</i>. -ιῆες, OD. <i>22, 384 ; gén</i>. -ιήων, CALL. <i>Dian. 196 ; acc</i>. -ιῆας, OD. <i>16, 349 ;</i> NIC. <i>Th. 823</i>.</p><p><b>Étym</b>. ἅλς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλιευς - ἁλιεύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G232":"<h1>halieuo</h1>\n<p>Strong n° 232 <i>Prononciation [hal-ee-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pêcher du poisson</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁλιεύω</b> <font color=\"brown\">[ᾰ]</font> pêcher, <i>d’où :</i><br><b> 1</b> être pêcheur, faire le métier de pêcheur, PLUT. <i>Ant. 29, M. 965</i> b ; NT. <i>Joh. 21, 3 ;</i><br><b> 2</b> prendre <i>ou</i> chercher à prendre en pêchant, <i>acc</i>. EPICH. (ATH. <i>319</i> f, <i>320</i> c, <i>etc.) ; fig</i>. SPT. <i>Jer. 16, 16 ;</i><br><b><i>Moy</i></b>. pêcher (par amusement) PLAT. COM. (ATH. <i>328</i> f); POLYEN <i>8, 24, 6 ;</i> DC. <i>55, 32</i>.<p><b>Étym</b>. ἁλιεύς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλιευω - ἁλιεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G233":"<h1>halizo</h1>\n<p>Strong n° 233 <i>Prononciation [hal-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>saler, assaisonner de sel, asperger de sel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁλίζω ²</b> <font color=\"brown\">[ᾱ]</font> <font color=\"darkgreen\">(<i>ao</i>. ἥλισα <font color=\"brown\">[ῐ]</font>; <i>pass. f</i>. ἁλισθήσομαι, <i>ao</i>. ἡλίσθην, <i>pf</i>. ἥλισμαι)</font> rassembler (une troupe, une armée, <i>etc.) acc</i>. HDT. <i>1, 77, etc. ;</i> EUR. <i>H.f. 408 ;</i> APP. <i>Civ. 4, 65 ;</i> εἰς ἕν, EUR. <i>Her. 403 ;</i> εἰς ταὐτόν, PLAT. <i>Crat. 409</i> a, rassembler en une masse, en un groupe, <i>etc. ; au pass</i>. être rassemblé, se rassembler, HDT. <i>1, 63, etc. ;</i> XÉN. <i>An. 2, 4, 3, etc</i>.<p><b>➼</b> <i>Part. pf. ion</i>. ἁλισμένος, HDT. <i>4, 118 ; 7, 172. Chez les Att. plutôt le composé</i> συναλίζω.</p><p><b>Étym</b>. ἁλής.</p><b>ἁλίζω ¹</b> <font color=\"darkgreen\">(<i>f. pass</i>. ἁλισθήσομαι ; <i>pf. pass</i>. ἥλισμαι)</font> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> saler, ARSTT. <i>H.A. 6, 15, 10 ; Probl. 21, 5 ;</i> NT. <i>Marc. 9, 49 ;</i><br><b> 2</b> nourrir avec du sel <i>ou</i> des aliments salés, ARSTT. <i>H.A. 8, 10, 2</i>.<p><b>Étym</b>. ἅλς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλιζω - ἁλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G234":"<h1>alisgema</h1>\n<p>Strong n° 234 <i>Prononciation [al-is'-ghem-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souillure, pollution, condamnation, contamination</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλίσγημα</b> <b>ατος (τὸ)</b> souillure, NT. <i>Ap. 25, 20</i>.<p><b>Étym</b>. ἀλισγέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλισγημα - ἀλίσγημα</font>\n<br><br>vient de alisgeo (souiller)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G235":"<h1>alla</h1>\n<p>Strong n° 235 <i>Prononciation [al-lah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mais\n<ol type=\"a\">\n<li>néanmoins, tout de même, malgré</li>\n<li>une objection</li>\n<li>une exception</li>\n<li>une restriction</li>\n<li>non, plutôt, oui, de plus</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλλά</b> <font color=\"brown\">[λᾰ]</font> <i>conj. adversative,</i> mais (<i>litt</i>. d’un autre côté, autrement) :<br><b>   I</b> <i>entre deux prop. :</i><br><b> 1</b> <i>après une prop. affirm. en relat. avec</i> μέν : αὐτὸς μὲν ἐγὼ μενέω νεῶν ἐν ἀγῶνι, ἀλλ' ἕταρον πέμπω, IL. <i>16, 240,</i> quant à moi je resterai dans cet endroit où sont réunis les vaisseaux, mais j’envoie mon compagnon (pour combattre) ;<br><b> 2</b> <i>après une prop. nég.:</i> οὔ τ' ἄρα Τρωσίν, ἀλλὰ σοὶ μαχούμεθα, SOPH. <i>Ph. 1253,</i> ce n’est certes pas contre les Troyens, mais contre toi que nous combattrons ; οὐ χαλεπήν, ἀλλὰ παντάπασιν ἀδύνατον, XÉN. <i>An. 5, 6, 10,</i> non pas difficile, mais tout à fait impossible ; <i>en ce sens</i> οὐ, μή <i>souv. accompagné de</i> μόνον, <i>et</i> ἀλλά <i>seul ou suivi de</i> καί : οὐ μόνον ἅπαξ, ἀλλὰ πολλάκις, PLAT. <i>Phædr. 228</i> a, non seulement une fois, mais plusieurs ; οὐ μόνον… ἀλλὰ καί, ATT. <i>etc</i>. non seulement… mais encore ; <i>de même</i> οὐχ ὅπως (<i>ou</i> μὴ ὅπως) … ἀλλά, ATT. ; μὴ ὅτι (<i>ou</i> οὐχ ὅτι) … ἀλλά, ATT. non seulement… mais encore ; <i>après une prop. nég. ou interr. représentée par</i> οὐ, οὔ τις, οὐδείς, <i>ou</i> τίς, <i>accompagnés ou non de</i> ἄλλος <i>ou de</i> ἕτερος, ἀλλά <i>peut se traduire par</i> que, excepté, sinon : ἔπαισεν οὔτις… ἀλλ' ἐγώ, SOPH. <i>O.R. 1331,</i> nul n’a frappé, sinon moi ; ἄλλη πόλις οὐδεμία… ἀλλὰ Θρᾷκες, XÉN. <i>An. 6, 4, 2,</i> aucun autre État que les Thraces ; τίνες ἄλλοι ἀλλ' οἱ ἄδικοι ; XÉN. <i>Hier. 5, 2,</i> quels autres que les hommes injustes ? <i>dans cette construction,</i> ἀλλά <i>est souvent suivi de</i> ἤ : ἀργύριον μὲν οὐκ ἔχω ἀλλ' ἢ μικρόν τι, XÉN. <i>An. 7, 7, 53,</i> quant à de l’argent, je n’ai qu’une petite somme ; <i>de même dans les inscr. att. :</i> τὴν δὲ γῆν μὴ ἐξεῖναι ἐξάγειν μηδενὶ ἀλλ' ἢ εἰς αὐτὸ τὸ χωρίον, CIA. <i>2, 1055, 27 (345 av. J.C</i>.) quant à la terre, il n’est permis à personne de l’emporter, sinon pour la transporter dans le terrain même (<i>v. Meisterh. p. 214, 241</i>) ;<br><b> 3</b> <i>après une prop. affirm. et avant une prop. nég., au sens de</i> mais non, et non pas, et non : ἔνθ' ἄλλοι μὲν πάντες ἐπευφήμησαν Ἀχαιοί· ἀλλ' οὐκ Ἀτρείδῃ Ἀγαμέμνονι ἥνδανε θυμῷ, IL. <i>1, 24,</i> alors tous les autres Grecs l’approuvèrent, mais cela ne plaisait point au cœur de l’Atride Agamemnon ;<br><b> 4</b> <i>après une prop. commençant par</i> εἰ <i>ou</i> εἰ μή, ἀλλά (<i>ou</i> ἀλλά γε) <i>peut se traduire par</i> mais du moins <i>ou simpl</i>. du moins : εἰ σῶμα δοῦλον, ἀλλ' ὁ νοῦς ἐλεύθερος, SOPH. <i>fr. 677,</i> si le corps est esclave, l’esprit du moins est libre ; εἰ μὴ πάντα, ἀλλὰ πολλά γε ἴστε, DIN. <i>2, 15,</i> si vous ne savez pas tout, du moins vous savez beaucoup ; εἰ δὲ μὴ ὁρῶ, ἀλλ' ἀκούω γε, PLAT. <i>Gorg. 470</i> d, si je ne vois pas, du moins j’entends ; <i>en ce sens,</i> ἀλλά <i>est souv. renforcé par</i> οὖν : εἰ μὴ… ἀλλ' οὖν, PLAT. <i>Leg. 859</i> b, <i>885</i> e, <i>918</i> c, <i>etc</i>. si… ne pas…, du moins donc ; <i>dans cette construction, la prop. commençant par εἰ peut se sous-entendre :</i> ὦ θεοὶ πατρῷοι, συγγένεσθέ γ' ἀλλὰ νῦν, SOPH. <i>El. 411,</i> ô dieux de mes pères, aujourd’hui du moins assistez-moi ! (<i>s.-e</i>. si vous ne l’avez pas fait auparavant) ;<br><b>   II</b> <i>au commenc. d’une phrase :</i><br><b> 1</b> <i>c. transition :</i> ἀλλὰ καὶ ὡς, IL. <i>1, 116</i> (je la préfère même à Clytemnestre), toutefois même ainsi (je consens à la rendre); ἀλλ' οὐδ' ὡς, OD. <i>1, 6</i> (son cœur endura mille souffrances, tandis qu’il luttait pour sauver ses compagnons), mais, même à ce prix, il ne put (les sauver) ;<br><b> 2</b> <i>c. objection à une pensée antérieure exprimée ou s.-e. :</i> ἀλλὰ μάλ' ὤφελλες Διΐ τ' ἄλλοισίν τε θεοῖσιν ῥέξας ἱερὰ κάλ' ἀναϐαινέμεν, OD. <i>4, 472,</i> eh bien mais en vérité tu aurais dû, avant de t’embarquer, offrir de beaux sacrifices à Zeus et aux autres dieux (si tu voulais retourner promptement dans ta patrie); <i>cf</i>. XÉN. <i>Conv. 1, 1 ;</i><br><b> 3</b> <i>en réponse à une prop nég. où la négation n’est pas exprimée, et où l’on sous-entend</i> « non certes » ESCHL. <i>Pers. 344 ;</i><br><b> 4</b> <i>pour interrompre brusquement un développement :</i> ἀλλὰ ταῦτα μὲν τί δεῖ λέγειν ; SOPH. <i>Ph. 11,</i> mais à quoi bon parler de cela ? <i>cf. Ph. 1291 ;</i><br><b> 5</b> <i>souv. dans le dialogue, au sens de</i> eh bien mais ; eh bien : ἀγαθὸν εἰ βούλει με καλεῖν, ἀλλὰ βούλομαι, PLAT. <i>Gorg. 449</i> a, veux-tu m’appeler bon ? eh bien mais j’y consens ; ἀλλ' ὁμολογῶ, PLAT. <i>Gorg. 476</i> d, eh bien, j’en conviens ; <i>cf</i>. EUR. <i>Hec. 391, etc. ;</i><br><b> 6</b> <i>en réponse à une object. dans la loc</i>. ἀλλ' ὅμως (<i>sans verbe</i>) mais néanmoins, mais cependant, tout de même, EUR. <i>Or. 1023 ;</i> AR. <i>Ach. 408 ;</i><br><b> 7</b> <i>c. exhortation au sens de</i> allons ! ἀλλ' ἄγε, IL. <i>13, 292 ; 22, 254 ; 23, 537 ; 24, 618, etc. ;</i> OD. <i>13, 215, etc. ;</i> mais voyons ! <i>particul. avec un impér. :</i> ἀλλ' ἄγ'… ἴτω, IL. <i>20, 355,</i> mais voyons, qu’un homme aille, <i>etc. ; cf</i>. IL. <i>5, 221, etc. ; sans</i> ἄγε, <i>avec un impér. ou un sbj</i>. ἀλλ' ἴομεν, IL. <i>10, 126 ;</i> ἀλλὰ πορευώμεθα, XÉN. <i>An. 6, 5, 14,</i> allons, marchons ! <i>cf</i>. XÉN. <i>Cyr. 1, 5, 13 ;</i> EUR. <i>Ph. 473, etc. ;</i> PLAT. <i>Rsp. 327</i> b, <i>Prot. 311</i> a, <i>etc. ;</i><br><b> 8</b> <i>pour renforcer une affirm. ou une nég. :</i> νὴ τοὺς θεοὺς ἀλλ' ἐπιθυμῶ, PLAT. <i>Gorg. 481</i> c, par les dieux, mais certes je désire ; μὰ τὸν Δία ἀλλ' ἐγώ… PLAT. <i>Gorg. 463</i> d, par Zeus, certes non je… <i>etc. ; avec</i> ἀλλά <i>redoublé :</i> μὰ Δί' ἀλλ' οὐκ ἠγνόουν ἔγωγε, ἀλλὰ σαφῶς ἐγίγνωσκον, PLAT. <i>1 Alc. 110</i> c, non certes, par Zeus, je ne l’ignorais pas ; au contraire je savais très bien ;<br><b>   III</b> ἀλλά <i>forme des locut. avec diverses particules :</i><br><b> 1</b> ἀλλ' ἄρα, mais alors, <i>au sens d’une transit</i>. IL. <i>6, 418, ou pour introduire une object. fondée sur ce qui précède,</i> PLAT. <i>Ap. 25</i> a ;<br><b> 2</b> ἀλλὰ γάρ <i>ou</i> ἀλλὰ… γάρ, mais… car, mais en effet, <i>litt</i>. mais (cela n’est pas) car, <i>etc. ; avec deux verbes dépendant l’un de</i> ἀλλά, <i>l’autre de</i> γάρ, SOPH. <i>Ph. 81 ;</i> EUR. <i>Ph. 1307 ; le verbe dépendant de</i> ἀλλά <i>est qqf. s.-e</i>. HDT. <i>8, 8 ;</i> ESCHL. <i>Pr. 941, etc. ; particul. pour prévoir une objection :</i> ἀλλὰ γὰρ φήσει τις, PLAT. <i>Rsp. 365</i> c, mais en effet, dira-t-on, <i>litt</i>. mais (cela n’est pas) dira-t-on, car, <i>etc. ;</i><br><b> 3</b> ἀλλ' οὖν, eh bien donc, eh bien alors, PLAT. <i>Prot. 327</i> c ; AR. <i>Pl. 1148, etc. ; ou pour marquer une concession,</i> eh bien donc, soit, PLAT. <i>Prot. 310</i> a ;<br><b> 4</b> οὐ μὴν ἀλλά, néanmoins : ὁ ἵππος πίπτει καὶ μικροῦ αὐτὸν ἐξετραχήλισεν οὐ μὴν ἀλλ' ἐπέμεινεν ὁ Κῦρος, XÉN. <i>Cyr. 1, 4, 8,</i> le cheval tombe et peu s’en fallut qu’il ne précipitât Cyrus ; mais ce dernier resta en selle (<i>litt</i>. οὐ μὴν ἐξετρ. ἀλλ' ἐπέμ. ὁ Κ.) ;<br><b> 5</b> ἀλλά <i>se joint encore à d’autres particules qui le renforcent simplement ;</i> ἀλλὰ καὶ… δέ, XÉN. <i>Œc. 11, 22 (ex. d’ailleurs douteux</i>), mais certes ; ἀλλ' ἤτοι, IL. <i>1, 140 ;</i> ἀλλὰ δή, SOPH. <i>Aj. 1271, O.C. 586 ;</i> ἀλλὰ μὲν δή, PLAT. <i>Theæt. 143</i> b ; ἀλλά τοι, ESCHL. <i>Pers. 795 ;</i> ἀλλὰ μέντοι, PLAT. <i>Rsp. 331</i> e, <i>Prot. 331</i> c, <i>Phæd. 108</i> d, <i>etc. ;</i> ἀλλὰ μήν, EUR. <i>I.A. 1368 ;</i> XÉN. <i>Mem. 1, 1, 6, etc. ;</i> PLAT. <i>Phæd. 75</i> a, <i>Rsp. 370</i> d, <i>etc. ;</i> ἀλλὰ μὴν καί, XÉN. <i>Mem. 1, 2, 4 ;</i> ἀλλὰ μὴν καὶ… γε, PLAT. <i>Rsp. 389</i> b, <i>etc. ;</i> ἀλλὰ μήν που, PLAT. <i>Euthyd. 281</i> a, <i>etc</i>. mais certes, mais bien certainement.<p><b>➼</b> ἀλλά <i>est qqf. placé après un ou plusieurs mots :</i> λέγ' ἀλλὰ τοῦτο, SOPH. <i>El. 417,</i> eh bien, dis-le ; <i>cf</i>. SOPH. <i>O.C. 1272, El. 331 ;</i> EUR. <i>I.A. 1239, Hec. 388, etc</i>.</p><p><b>Étym</b>. <i>plur. neutre de</i> ἄλλος, <i>avec chang. d’accent</i>.</p><b>ἀλλᾷ</b> <i>v</i>. ἄλλῃ.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλα - ἀλλά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n633 fois dans 598 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (37)</li>\n<li>Marc (42)</li>\n<li>Luc (36)</li>\n<li>Jean (103)</li>\n<li>Actes (29)</li>\n<li>Romains (68)</li>\n<li>1 Corinthiens (73)</li>\n<li>2 Corinthiens (68)</li>\n<li>Galates (23)</li>\n<li>Ephésiens (13)</li>\n<li>Philippiens (15)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (13)</li>\n<li>2 Thessaloniciens (5)</li>\n<li>1 Timothée (12)</li>\n<li>2 Timothée (12)</li>\n<li>Tite (4)</li>\n<li>Philémon (2)</li>\n<li>Hébreux (16)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (15)</li>\n<li>2 Pierre (6)</li>\n<li>1 Jean (13)</li>\n<li>2 Jean (4)</li>\n<li>3 Jean (3)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G236":"<h1>allasso</h1>\n<p>Strong n° 236 <i>Prononciation [al-las'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>changer, échanger une chose pour une autre, transformer, troquer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλλάσσω</b> <i>att</i>. <b>ἀλλάττω</b> <font color=\"darkgreen\">(<i>f</i>. -άξω, <i>ao</i>. ἤλλαξα, <i>pf. inus. ; pass. f.2</i> ἀλλαγήσομαι, <i>ao</i>. ἠλλάγην <i>ou</i> ἠλλάχθην, <i>pf</i>. ἤλλαγμαι)</font><br><b>   I</b> changer, altérer : ἀ. χροιάν, EUR. <i>Med. 1168,</i> changer de couleur ; ἀ. τὸ ἑαυτοῦ εἶδος εἰς πολλὰς μορφάς, PLAT. <i>Rsp. 380</i> d, changer ses traits en nombreuses formes ; <i>avec le dat</i>. πέτραις ἀλλ. δέμας, ORPH. <i>Arg. 1297,</i> changer le corps en pierre ;<br><b>   II</b> échanger :<br><b> 1</b> prendre en échange : θνητὸν εἶδος, EUR. <i>Bacch. 53,</i> échanger ses traits pour ceux d’un mortel ; τί τινος, THGN. <i>21, ou</i> τινί τι, SOPH. <i>fr. 400,</i> prendre une chose en échange d’une autre ; πόλιν ἐκ πόλεως, PLAT. <i>Pol. 289</i> e, aller de ville en ville ; χώραν, PLAT. <i>Parm. 139</i> a, changer de pays ; ἀλλάξας ἐξ ἕδρας, EUR. <i>I.T. 193,</i> le soleil ayant quitté sa station (céleste) ;<br><b> 2</b> donner en échange : τι ἀντί τινος, EUR. <i>Alc. 661, ou</i> τινός τι, ESCHL. <i>Pr. 967,</i> donner une chose en échange d’une autre ; φόνον φονεῦσιν, EUR. <i>El. 89,</i> rendre meurtre pour meurtre ;<br><b> 3</b> prendre à son tour : σκῆπτρα, EUR. <i>Ph. 74,</i> le sceptre ;<br><b> 4</b> quitter, abandonner : οὐράνιον φῶς, SOPH. <i>Ant. 944,</i> quitter la lumière céleste ; ἀλλάσσων εὐδαιμονίαν, EUR. <i>I.T. 1117</i> (celui qui) quitte le bonheur ;<br><b><i>Moy</i></b>. <font color=\"darkgreen\">(<i>f</i>. ἀλλάξομαι, <i>ao</i>. ἠλλαξάμην)</font><br><b>   I</b> changer pour soi : τὴν πολιτείαν, POL. changer son système de gouvernement ;<br><b>   II</b> échanger pour soi :<br><b> 1</b> prendre en échange : τί τινος, ANT. <i>138, 34 ;</i> τί τινι, HDT. <i>7, 152 ;</i> PLAT. <i>Leg. 915</i> d ; τι ἀντί τινος, PLAT. <i>Rsp. 371</i> c, prendre une chose en échange d’une autre ;<br><b> 2</b> donner qqe ch. à soi en échange : τί τινος, THC. <i>8, 82,</i> donner une chose en échange d’une autre ;<br><b> 3</b> trafiquer, faire le commerce : πρός τινα, PLAT. <i>Leg. 915</i> e, avec qqn.<p><b>➼</b> <i>Pf</i>. ἤλλαχα <i>seul. dans les cps</i>. ἀπ-, δι-, μετ- ήλλαχα ; <i>pl.q.pf. pass. 3 sg</i>. ἤλλακτο, HDT. <i>2, 26 ;</i> LUC. <i>Tox. 30. Pass. fut.2</i> ἀλλαγήσομαι, LUC. <i>Im. 2 ; ao.1</i> ἠλλάχθην, ANTH. <i>7, 336 ; ao.2 plus us. et seul att</i>. IS. <i>4, 13 Baiter-Sauppe ;</i> LUC. <i>Gall. 16. Moy. ao. 2 sg. poét</i>. ἠλλάξαο, ANTH. <i>7, 373</i>.</p><p><b>Étym</b>. ἄλλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλασσω - ἀλλάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G237":"<h1>allachothen</h1>\n<p>Strong n° 237 <i>Prononciation [al-lakh-oth'-en]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>provient d'un autre lieu, par un autre endroit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλλαχόθεν</b> <font color=\"brown\">[ᾰχ]</font> <i>adv</i>. en venant d’ailleurs, ANT. <i>124, 16 ;</i> PLUT. <i>M. 29</i> c ; SPT. <i>Esth. 4, 14</i>.<p><b>Étym</b>. *ἀλλαχο-, -θεν.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλοχθεν - ἀλλαχόθεν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G238":"<h1>allegoreo</h1>\n<p>Strong n° 238 <i>Prononciation [al-lay-gor-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler allégoriquement, ou par figure</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλληγορέω</b> <b>ἀλλ·ηγορέω-ῶ</b>, parler par allégorie, faire comprendre par allégorie, ATH. <i>69</i> c ; PLUT. <i>M. 363</i> c, <i>996</i> b ; <i>au pass</i>. être dit sous forme d’allégorie, NT. <i>Gal. 4, 24</i>.<p><b>Étym</b>. ἄλλος, ἀγορεύω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλληγορεω - ἀλληγορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G239":"<h1>allelouia</h1>\n<p>Strong n° 239 <i>Prononciation [al-lay-loo'-ee-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>alléluia (Angl. Alléluia) = « Louez l'Eternel ! »\n<ol><li>louez l'Eternel, Hallelujah <a class=\"ref\" data-r=\"PSA104.35\">Ps 104.35</a></li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλληλουια</font> &lt; הללויה - <font face=\"Georgia\">ἁλληλουϊά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Interjection impératif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G240":"<h1>allelon</h1>\n<p>Strong n° 240 <i>Prononciation [al-lay'-lone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'un l'autre, réciproquement, mutuellement, les uns les autres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλλήλων</b> <i>gén. pl. sans nomin. (dat</i>. -οις, -αις, -οις ; <i>acc</i>. -ους ; ας, -α ; <i>duel gén</i>. -οιν, -αιν, -οιν ; <i>acc</i>. -ω, -α, -ω) :<br><b> 1</b> <i>d’ord. en parl. de plus de deux pers. ou choses,</i> les uns les autres ; ἀλλήλων ἀλεείνοντες βέλεα, IL. <i>17, 374,</i> évitant les traits les uns des autres : ἠδίκουν ἀλλήλους, PLAT. <i>Prot. 322</i> b, ils se faisaient tort les uns aux autres ; πρὸς αὑτὰ καὶ πρὸς ἄλληλα, PLAT. <i>Gorg. 451</i> c, les choses considérées en elles-mêmes et dans leurs rapports les unes avec les autres ; <i>cf</i>. IL. <i>4, 62, etc. ;</i> OD. <i>1, 209, etc. ;</i> ESCHL. <i>Pr. 200, etc. ;</i> THC. <i>8, 66 ;</i> PLAT. <i>Tim. 38</i> d, <i>54</i> b ; <i>Prot. 322</i> b, <i>etc. ;</i> ὁ δι' ἀλλήλων τρόπος, DL. <i>9, 89 ; ou</i> ὅρος, NICOM. <i>Theol. 75,</i> le cercle vicieux ;<br><b> 2</b> <i>en parl. de deux pers. ou de deux choses,</i> l’un l’autre : ἐγὼ μὲν καὶ αὐτός, ὦ Πρωταγόρα τε καὶ Σώκρατες, ἀξιῶ ὑμᾶς συγχωρεῖν ἀλλήλοις, <i>etc</i>. PLAT. <i>Prot. 337</i> a, quant à moi, Protagoras et Socrate, je vous demande de vous mettre d’accord l’un avec l’autre, <i>etc</i>.<p><b>➼</b> <i>Duel gén. épq</i>. -οιιν, IL. <i>10, 65. Plur. dor</i>. ἀλλάλων, ἀλλάλοις, <i>etc</i>. <font color=\"brown\">[λᾱ]</font> PD. <i>P. 4, 397, etc. ;</i> THCR. <i>Idyl. 12, 15, etc. Sg. avec un n. collect. dans une inscr. att. :</i> κεράμῳ ἁρμόττοντι πρὸς ἄλληλον, briques s’ajustant les unes avec les <i>autres,</i> CIA. <i>2, 1054, 58 (347 av. J.C., v. Meisterh. p. 160, 4</i>).</p><p><b>Étym</b>. ἄλλος redoublé.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλληλων - ἀλλήλων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom pluriel réciproque</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n103 fois dans 94 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (6)</li>\n<li>Luc (10)</li>\n<li>Jean (15)</li>\n<li>Actes (9)</li>\n<li>Romains (14)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (5)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (4)</li>\n<li>1 Jean (6)</li>\n<li>2 Jean (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G241":"<h1>allogenes</h1>\n<p>Strong n° 241 <i>Prononciation [al-log-en-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>qui vient d'une autre race, un étranger</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλλογενής</b> <b>ἀλλο·γενής, ής, ές</b>, d’une autre race, SPT. <i>Ezech. 44, 9 ; Esaï. 56, 3 ; 61, 5 ; Jer. 51, 51 ;</i> NT. <i>Luc. 17, 18</i>.<p><b>Étym</b>. ἄλλος, γένος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλο-γενης - ἀλλογενής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G242":"<h1>hallomai</h1>\n<p>Strong n° 242 <i>Prononciation [hal'-lom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sauter, faire un bond</li>\n<li>jaillir, jaillissement d'eau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἅλλομαι</b> <font color=\"darkgreen\">(<i>impf</i>. ἡλλόμην, <i>f</i>. ἁλοῦμαι, <i>ao</i>. ἡλάμην, <i>v. ci-dessous</i>)</font> <font color=\"brown\">[ᾰλου]</font> sauter, bondir, s’élancer :<br><b> 1</b> <i>en parl. de pers. ou d’anim. :</i> ἀφ' ἵππων, IL. <i>16, 733, 755 ; ou</i> ἐξ ἵππων, IL. <i>24, 269,</i> sauter d’un char ; ἐξ ὀχέων χαμᾶζε, IL. <i>6, 103,</i> sauter d’un char à terre ; εἰς ἅλα, IL. <i>1, 537,</i> sauter dans la mer ; ἐπί τινι, OD. <i>22, 80,</i> sauter sur qqn, s’élancer contre qqn ; εἰς ἵππους, IL. <i>11, 192, 207,</i> sauter sur son char ; <i>avec un simple acc</i>. ἅλλ. πόντον, CALL. <i>Dian. 195,</i> sauter dans la mer ; τάφρον, OPP. <i>C. 1, 83,</i> sauter un fossé ; <i>avec l’inf</i>. ἅλλ. θέειν, HH. <i>Cer. 390 ; ou</i> πέτεσθαι, HH. <i>Ap. 448,</i> s’élancer pour courir <i>ou</i> voler ;<br><b> 2</b> <i>en parl. de choses (trait,</i> IL. <i>4, 125 ; son,</i> PLAT. <i>Phædr. 253</i> c ; <i>lumière,</i> PLUT. <i>M. 936</i> b, <i>937</i> a, <i>œil qui tressaille,</i> THCR. <i>Idyl. 3, 37, etc</i>.).<p><b>➼</b> <i>Fut. dor</i>. ἁλεῦμαι, THCR. <i>Idyl. 3, 25 ; 5, 144. Ao.1</i> ἡλάμην, BATR. <i>225, 249, etc. ; 3 sg. dor</i>. ἅλατο <font color=\"brown\">[ᾱᾰ]</font> THCR. <i>Idyl. 19, 4 ; 23, 60 ; inf</i>. ἅλασθαι, EL. <i>Ep. rust. 16 ; part</i>. ἁλάμενος, AR. <i>Av. 1395 ;</i> XÉN. <i>An. 4, 2, 17. Ao.2</i> ἡλόμην, XÉN. <i>Hell. 4, 4, 11 dout. d’où sbj. 3 sg</i>. ἅληται, IL. <i>21, 536 ; épq</i>. ἅλεται, IL. <i>11, 192, 207 ; opt</i>. ἁλοίμην, XÉN. <i>Mem. 1, 3, 9 ;</i> ANTH. <i>7, 36 (dor</i>. ἁλοίμαν <font color=\"brown\">[ᾱᾱ]</font> THCR. <i>Idyl. 5, 16</i>); <i>inf</i>. ἁλέσθαι, OPP. <i>C. 1, 83 ; part</i>. ἁλόμενος, ESCHL. <i>Eum. 368. Ao. avec les formes sync. 2 sg</i>. ἆλσο, IL. <i>16, 754 ; 3 sg</i>. ἆλτο, IL. <i>5, 111 ; part</i>. ἅλμενος (<i>mais</i> ἄλμ. <i>dans</i> ἐπάλμενος) OPP. <i>H. 5, 666</i>.</p><p><b>Étym</b>. <i>p</i>. *ἅλϳομαι, <i>de la R. indo-europ</i>. *sel-, sauter, <i>cf. lat</i>. săliō.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλομαι - ἅλλομαι</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G243":"<h1>allos</h1>\n<p>Strong n° 243 <i>Prononciation [al'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un autre, autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄλλος</b> <b>η, ο</b>, autre :<br><b>A</b> un autre :<br><b>   I</b> encore un :<br><b> 1</b> <i>en gén</i>. Ζεῦ, ἄλλοι τε θεοί, IL. <i>6, 476,</i> ô Zeus et autres dieux ! <i>avec le gén</i>. ἄλλος Ἀχαιῶν, IL. <i>16, 141,</i> un autre d’entre les Grecs ; <i>p. opp. à un autre</i> ἄλλος : ἄλλος μὲν… ἄλλος δέ, IL. <i>22, 493, etc. ;</i> ATT. l’un… l’autre ; <i>dans une même prop., construit avec un autre</i> ἄλλος, <i>ou avec un adv. dérivé de</i> ἄλλος : ἄλλος ἄλλο λέγει, XÉN. <i>An. 2, 1, 15, etc</i>. l’un dit une chose, l’autre une autre ; ἄλλος γάρ τ' ἄλλοισιν ἀνὴρ ἐπιτέρπεται ἔργοις, OD. <i>14, 228,</i> car l’un se plaît à un travail, l’autre à un autre ; ἄλλος ἄλλῃ, ἄλλος ἄλλοθεν, <i>etc</i>. (<i>v</i>. ἄλλῃ, ἄλλοθεν, <i>etc</i>.); <i>p. opp. à</i> ἕτερος : ἕτερος μὲν… ἄλλο δέ, IL. <i>9, 313 ;</i> ἄλλο μὲν… ἕτερον δέ, HDT. <i>1, 32,</i> une chose… une autre ; <i>avec un adj. indéterminé :</i> ἄλλος τις <i>ou</i> τὶς ἄλλος, HOM. qqe autre : εἴ τις ἄ. THC. <i>6, 32 ;</i> εἴ τις καὶ ἄ. XÉN. <i>An. 1, 4, 15,</i> s’il en était <i>ou</i> s’il en est ; οὐδεὶς ἄ., οὐδέ τις ἄλλος (<i>v. ci-dessous</i> B, I) aucun autre ; ἄ. πολλοί <i>ou</i> πολλοὶ ἄ. ATT. beaucoup d’autres ; ἄ. τοιοῦτοι <i>ou</i> τοσοῦτοι, ATT. d’autres semblables <i>ou</i> en aussi grand nombre ; ἄλλος ὁστισοῦν, PLAT. <i>Gorg. 471</i> d ; ἄλλο ὁτιοῦν, PLAT. <i>Parm. 164</i> b, <i>etc</i>. un autre quelconque, n’importe quel autre ; une autre chose quelconque, n’importe quelle autre chose ; <i>après un compar. ou un superl</i>. οὔτις σεῖο νεώτερος ἄλλος Ἀχαιῶν, IL. <i>15, 569,</i> nul autre des Grecs n’est plus jeune que toi ; ὀϊζυρώτατος ἄλλων, OD. <i>5, 105,</i> le plus malheureux de tous ; <i>avec un n. de nombre :</i> τέταρτος ἄ. ESCHL. <i>Sept. 486,</i> un quatrième ; <i>cf</i>. HDT. <i>4, 54 ;</i> SOPH. <i>Ant. 1295 ; uni par</i> καί <i>à un autre</i> ἄλλος : ἄ. καὶ ἄ. XÉN. <i>An. 1, 5, 12,</i> un et un autre, un ou deux ; ἄλλο καὶ ἄλλο, XÉN. <i>Cyr. 4, 1, 15,</i> une chose après une autre ; <i>pléon. au sens de</i> en outre : ἅμα τῇγε καὶ ἀμφίπολοι κίον ἄλλαι, OD. <i>6, 84,</i> avec elle vinrent aussi ses servantes ; οὐ γὰρ ἦν χόρτος οὐδὲ ἄλλο δένδρον οὐδέν, XÉN. <i>An. 1, 5, 5,</i> il n’y avait ni fourrage ni arbre d’aucune sorte. — <i>Précédé de l’article</i> (ὁ ἄλλος, ἡ ἄλλη, <i>etc.) et qqf. (chez Hom. et les Trag.) sans article, il signifie d’ord</i>. le reste : ὁ ἄ. στρατός, XÉN. <i>Cyr. 6, 4, 1 ;</i> ἡ ἄλλη Ἑλλάς, XÉN. <i>Hell. 4, 1, 15,</i> le reste de l’armée, de la Grèce ; ὁ ἄ. χρόνος, ATT. le reste du temps, <i>d’ord. en parl. du passé (p. opp. à</i> ὁ λοιπὸς χρόνος, l’avenir), <i>rar. en parl. de l’avenir,</i> LYS. <i>139, 45 ;</i> DÉM. <i>22, 3 ; plur</i>. οἱ ἄλλοι, ATT. ; <i>par crase ion</i>. ὧλλοι, HDT. <i>1, 48, 125 ; 2, 14, 36 ; 7, 67 ; 9, 109,</i> les autres (<i>lat</i>. ceteri); <i>qqf. joint à un pron. pers</i>. ἧμας τοὺς ἄλλους, IL. <i>8, 211,</i> nous autres ; <i>cf</i>. IL. <i>20, 135 ;</i> LUC. <i>D. mer. 5 ;</i> τὰ ἄλλα, <i>par crase</i> τἄλλα <i>ou</i> τἆλλα ; <i>rar</i>. τὸ ἄλλο, ATT. les autres choses, le reste (<i>lat</i>. cetera) <i>ou adv</i>. du reste ; <i>ttef</i>. τῇ ἄλλῃ ἡμέρᾳ, τῷ ἄλλῳ ἔτει, ATT. le jour suivant, l’année suivante. — <i>La loc</i>. οἵ τε ἄλλοι… καί, τά τε ἄλλα… καί <i>signifie</i> les autres… et en particulier (celui-ci), les autres choses… et en particulier (celle-ci) : τά τε ἄλλα ἐτίμησε καὶ ἔδωκε, XÉN. <i>An. 1, 3, 3,</i> entre autres marques d’estime il lui donna (<i>litt</i>. il l’honora d’autres marques d’estime et en particulier lui donna) ;<br><b>   II</b> <i>en parl. de deux :</i><br><b> 1</b> l’autre : τὴν τοῦ Ἡφαίστου (τέχνην) καὶ τὴν ἄλλην τὴν τῆς Ἀθηνᾶς, PLAT. <i>Prot. 321</i> d, l’art d’Hèphæstos, et l’autre celui d’Athèna ; <i>cf</i>. PLAT. <i>Phædr. 276</i> a, <i>Phæd. 58</i> d ; οὐδ' ἄλλος = οὐδέτερος, ni l’un ni l’autre, THCR. <i>Idyl. 6, 45 ;</i><br><b> 2</b> un second : ἄλλος οὗτος Ἡρακλῆς, PLUT. <i>Thes. 29,</i> c’est un autre Hèraklès ; <i>cf</i>. ESCHL. <i>Sept. 424, Eum. 6, Suppl. 220, etc. ;</i><br><b>B</b> autre, d’autre sorte, différent :<br><b>   I</b> <i>abs</i>. IL. <i>13, 64 ; 21, 22 ; pléon</i>. ἄλλος ἕτερος, un autre, EUR. <i>Suppl. 573, Or. 345 ; avec un gén</i>. autre que : ἄλλα τῶν δικαίων, XÉN. <i>Mem. 4, 4, 25,</i> des choses autres que celles qui sont justes, <i>p. euphém. p</i>. τὰ ἄδικα ; <i>de même</i> ἄλλος παρά, <i>acc</i>. PLAT. <i>Phæd. 80</i> b, <i>etc. ;</i> ἄ. ἀντί, <i>gén</i>. ESCHL. <i>Pr. 467 ;</i> ἄ. πρό, <i>gén</i>. HDT. <i>3, 85 ;</i> ἄ. πλήν, SOPH. <i>Aj. 125 ;</i> ἄ. εἰ μή, HDT. <i>4, 94 ;</i> XÉN. <i>Cyr. 2, 2, 11,</i> autre que ; <i>particul</i>. ἄλλος ἤ <i>précédé de</i> τίς <i>ou de</i> οὐδείς : τίς ἄλλος ἢ 'γώ ; ESCHL. <i>Pr. 440,</i> quel autre que moi ? οὐδὲν ἄλλο ἤ, ATT. ; οὐδὲν ἄλλο γ' ἤ, ESCHL. <i>Pers. 209,</i> rien autre chose que ; <i>avec un verbe (cf. lat</i>. quid aliud quam, nihil aliud quam <i>suivi d’un verbe</i>) : τί ἄλλο οὗτοι ἢ ἐπεϐούλευσαν ; THC. <i>3, 39,</i> qu’ont-ils fait sinon conspirer ? οὐδὲν ἄλλ' ἢ συμϐουλεύουσιν, IS. <i>8, 37,</i> ils ne font rien autre chose que nous conseiller ; <i>de même</i> ἄλλο τί ποιῶ ἤ… ; ATT. fais-je autre chose que… ? <i>càd</i>. ne fais-je pas… ? <i>s.-e</i>. ποιῶ : ἄλλο τι (<i>s.-e</i>. ποιοῦμεν) ἢ ὁμολογοῦμεν ; PLAT. <i>Gorg. 470</i> b, ne sommes-nous pas d’accord ? <i>d’où, avec la valeur d’une loc. adv. :</i> τῷ διαλέγει σὺ νῦν ; ἄλλο τι ἢ ἐμοί ; PLAT. <i>1 Alc. 116</i> d, avec qui converses-tu en ce moment ? n’est-ce pas avec moi ? <i>abs</i>. ἄλλο τί ; <i>m. sign. :</i> ἄλλο τί ὁ ἀγαθὸς τῷ ἀγαθῷ μόνῳ φίλος ; PLAT. <i>Lys. 222,</i> n’est-il pas vrai que l’homme de bien n’est ami qu’avec l’homme de bien ? <i>de même</i> οὐδέ τις ἄλλος <i>suivi de</i> ἀλλά : οὐδέ τις ἄλλος… ἀλλ' ἄρα Κασσάνδρη, IL. <i>24, 699,</i> personne autre que Cassandre ; <i>cf</i>. IL. <i>21, 276, etc</i>. OD. <i>3, 378, etc. ;</i><br><b>   II</b> <i>par opp. à une idée antérieure :</i><br><b> 1</b> autre (que les nationaux), étranger : OD. <i>23, 274 ;</i> SOPH. <i>O.R. 230 ;</i> XÉN. <i>Hipp. 7, 2, etc. ;</i><br><b> 2</b> autre (que ce qui est), faux, non réel, OD. <i>4, 348 ; 17, 139 ;</i><br><b> 3</b> autre (que ce qui est juste), déshonnête, mauvais, PLUT. <i>M. 187</i> d.<p><b>➼</b> <i>Sans vocatif,</i> EM. <i>67, 2</i>.</p><p><b>Étym</b>. <i>indo-europ</i>. *h₂el-io-, autre ; <i>cf. lat</i>. alius.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλος - ἄλλος</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> comparé à  dénote un nombre qui distingue de différences qualitatives ;  ajoute ('un en outre'),  distingue ('un des deux') ; chaque  est un , mais tous les  ne sont pas un ;  dénote généralement une simple distinction entre des individus,  implique l'idée secondaire de différence de genre.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n155 fois dans 136 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (30)</li>\n<li>Marc (22)</li>\n<li>Luc (11)</li>\n<li>Jean (33)</li>\n<li>Actes (8)</li>\n<li>1 Corinthiens (23)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (2)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (17)</li>\n</ul>\n</td></tr>\n</table>","G244":"<h1>allotriepiskopos</h1>\n<p>Strong n° 244 <i>Prononciation [al-lot-ree-ep-is'-kop-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui veut s'occuper des affaires des autres, et qui n'est pas sage pour lui-même, délateur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλοτρι-επισκοπος - ἀλλοτριεπίσκοπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G245":"<h1>allotrios</h1>\n<p>Strong n° 245 <i>Prononciation [al-lot'-ree-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appartenant à d'autres</li>\n<li>étranger, pas de notre famille, un ennemi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλλότριος</b> <b>α, ον :<br> 1</b> qui concerne autrui, d’autrui : ἀλλοτρίων χαρίσασθαι, OD. <i>17, 452,</i> faire le généreux avec le bien d’autrui ; γναθμοῖσι γελοίων ἀλλοτρίοισιν, OD. <i>20, 347,</i> ils riaient d’un rire involontaire, <i>càd</i>. convulsif (<i>litt</i>. d’un rire qui ne venait pas d’eux, non voulu); τοῖς σώμασιν ἀλλοτριωτάτοις χρῶνται, THC. <i>1, 70,</i> ils exposent leur corps tout à fait comme s’il n’était pas à eux ;<br><b> 2</b> d’un autre pays, étranger, OD. <i>18, 219 ;</i> HDT. <i>3, 155 ; p. opp. à</i> οἰκεῖος, PLAT. <i>Euthyphr. 4</i> b ; <i>d’où</i> contraire, hostile, IL. <i>5, 214 ;</i> OD. <i>16, 102 ;</i> τινι, POL. <i>27, 13, 13 ;</i> πρός τινα, DS. <i>20, 4,</i> à qqn ; ἡ ἀλλοτρία, ISOCR. <i>218</i> a, la terre étrangère <i>ou</i> le pays ennemi ;<br><b> 3</b> qui ne concerne pas, étranger à : τινι, PLAT. <i>Conv. 179</i> c ; τινος, LYS. <i>190, 12 ;</i> DÉM. <i>289, 15 (décr</i>.) à qqn <i>ou</i> à qqe ch. ; <i>d’où</i> incompatible avec, <i>dat</i>. PLAT. <i>Rsp. 343</i> c ; <i>abs</i>. PLAT. <i>Rsp. 491</i> d.<br><i>● Cp</i>. -ώτερος, HDT. <i>3, 119 ;</i> PLAT. <i>Rsp. 491</i> d ; ARSTT. <i>Nic. 8, 12, 4, etc. ;</i> <i>● Sup</i>. -ώτατος, HDT. <i>3, 119 ;</i> THC. <i>l. c. ;</i> DS. <i>20, 4, etc</i>.<p><b>Étym</b>. ἄλλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλοτριος - ἀλλότριος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 13 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G246":"<h1>allophulos</h1>\n<p>Strong n° 246 <i>Prononciation [al-lof'-oo-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>étranger, celui qui est d'une autre nation, d'une autre tribu d'ou païen</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλλόφυλος</b> <b>ἀλλό·φυλος, ος, ον</b> <font color=\"brown\">[ῡ]</font> :<br><b> 1</b> d’une autre race, étranger, <i>en parl. de pers</i>. THC. <i>1, 102 ;</i> PLAT. <i>Leg. 629</i> d ; <i>en parl. de choses :</i> χθὼν ἀλλ. ESCHL. <i>Eum. 851,</i> terre étrangère ; πόλεμος ἀ. PLUT. <i>Cam. 23,</i> guerre étrangère ;<br><b> 2</b> d’une autre espèce, DS. <i>3, 18</i>.<p><b>Étym</b>. ἄλλος, φυλή.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλοφυλος - ἀλλόφυλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G247":"<h1>allos</h1>\n<p>Strong n° 247 <i>Prononciation [al'-loce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>autrement, pas de cette manière</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄλλως</b> <i>adv. :</i><br><b>   I</b> autrement :<br><b> 1</b> d’une autre manière, PLAT. <i>Gorg. 479</i> c ; οὕτως ἢ ἄλλως ; PLAT. <i>Phæd. 81</i> a ; ἄλλως ἢ οὕτως ; PLAT. <i>Gorg. 509</i> c (est-ce) ainsi ou autrement ? autrement ou ainsi ? οὕτως ἢ ἄ. πως, PLAT. <i>Phædr. 272</i> b, de cette manière ou de qqe autre ; ἄ. οὐδαμῶς, PLAT. <i>Parm. 163</i> c, <i>etc</i>. d’aucune autre manière ; οὐκ ἄλλως ἐρεῖς, EUR. <i>El. 226,</i> tu diras comme (moi); <i>avec le gén</i>. ἄ. ἔχειν τινός, DH. <i>6, 49,</i> être disposé autrement que qqn ; <i>avec une conj</i>. οὐκ ἄλλως ἤ, ARR. <i>An. 2, 17, 2 ;</i> οὐκ ἄλλως ἀλλά, POL. <i>10, 30, 5 ;</i> οὐκ ἄλλως εἰ μή, PAUS. <i>10, 25, 3,</i> non autrement que ; ἄλλως τε καί, ATT. pour d’autres raisons… et en particulier (pour celle-ci); <i>ou</i> sous d’autres rapports… et en particulier (sous celui-ci) ; <i>d’où</i> particulièrement, surtout : χαλεπόν ἐστι διαϐαίνειν τὸν ποταμὸν ἄλλως τε καὶ πολεμίων πολλῶν ἔμπροσθεν ὄντων, XÉN. <i>An. 5, 6, 3,</i> il est difficile de traverser le fleuve (pour d’autres raisons et) surtout lorsque l’ennemi est en force barrant le chemin ; οὐκ ἀηδές, ἄλλως τε καὶ τήνδε τὴν ὥραν, PLAT. <i>Phædr. 229</i> a, chose non désagréable, surtout en ce moment ; <i>cf</i>. ESCHL. <i>Suppl. 749, etc. ;</i> SOPH. <i>El. 1324, etc. ;</i> XÉN. <i>Mem. 2, 8, 1, etc. ; renforcé par</i> πάντως : ἄλλως τε πάντως καί, ESCHL. <i>Pr. 636, Eum. 726, Pers. 675, etc. ; de même :</i> ἄλλως τε, XÉN. <i>Cyr. 1, 6, 43, etc. m. sign. ; souv. suivi d’une conj</i>. ἄ. τε καὶ εἰ <i>ou</i> ἐάν, <i>etc.:</i> ἄλλως τε καὶ εἰ φίλος εἴη, LUC. <i>Nigr. 6,</i> surtout si c’est un ami (<i>cf</i>. XÉN. <i>Mem. 2, 6, 30, etc</i>.) : <i>ou</i> ἄλλως τ' ἐάν, XÉN. <i>Mem. 1, 2, 59 ;</i> ἄλλως τε καὶ ἐάν, PLAT. <i>Rsp. 377</i> d, <i>etc. ;</i> ἄλλως τε καὶ ἐπειδή, PLAT. <i>Ep. 320</i> c, <i>etc</i>. surtout lorsque <i>ou</i> puisque, <i>etc. ;</i> ἄ. τ' ἐπειδὴ καί, ISOCR. <i>Panath. 66, m. sign. ;</i><br><b> 2</b> autrement (qu’on ne pourrait croire) <i>càd</i>. mieux, IL. <i>14, 53 ;</i> OD. <i>8, 176 ;</i><br><b> 3</b> autrement (qu’il ne convient) <i>càd</i>. à tort, mal, injustement, DÉM. <i>1466, 5, etc. ; ou</i> au hasard, sans raison, OD. <i>14, 124 ;</i> HDT. <i>3, 16, etc. ; ou</i> en vain, inutilement, IL. <i>23, 144 ;</i> SOPH. <i>O.R. 1151, etc. ;</i> EUR. <i>Hec. 626, El. 57 ; répété deux fois,</i> EUR. <i>Hipp. 535 ; p. ext</i>. sans but, sans motif déterminé, EUR. <i>Hipp. 374 ; cf</i>. LUC. <i>D. deor. 20, 4 :</i> ταῦτά μοι δοκῶ ἄ. λέγειν, PLAT. <i>Phæd. 115</i> d, il me semble que je parle là inutilement : τὴν ἄλλως (<i>v</i>. τηνάλλως) <i>m. sign. ;</i><br><b> 4</b> autrement, <i>càd</i>. simplement : εἴδωλον ἄ. SOPH. <i>Ph. 947,</i> une pure image ; ἄ. ὄνομα, THC. <i>8, 78,</i> (la flotte phénicienne) qui n’était qu’un mot (non une réalité) <i>etc. ;</i><br><b>   II</b> en outre ; <i>en ce sens d’ord. construit avec</i> καί : ἀγήνωρ ἐστὶ καὶ ἄλλως, IL. <i>9, 699,</i> il est d’ailleurs orgueilleux ; τὸ σῶμα μάλα εὔρωστος, καὶ ἄλλως φιλόπονος, XÉN. <i>Hell. 6, 1, 6,</i> très vigoureux de corps, et en outre aimant la fatigue ; <i>cf</i>. HDT. <i>1, 60 ;</i> PLAT. <i>Phæd. fin, etc. ; ou avec</i> δέ : ἄ. δέ, HDT. <i>6, 105,</i> et d’ailleurs, et en outre ;<br><b>   III</b> d’ailleurs, SOPH. <i>O.R. 1114 ; d’ord. après</i> εἰ <i>ou</i> ἐπεί : εἰ ἄ. βουλοίατο, HDT. <i>8, 30,</i> si d’ailleurs eux-mêmes le voulaient ; ἐπείπερ ἄ. ESCHL. <i>Ch. 680,</i> puisque d’ailleurs.<p><b>Étym</b>. ἄλλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλλως - ἄλλως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G248":"<h1>aloao</h1>\n<p>Strong n° 248 <i>Prononciation [al-o-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>battage, fouler le grain, dépiquer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλοάω</b> <b>ἀλοάω-οῶ</b> <font color=\"darkgreen\">(<i>f</i>. οήσω, <i>ao</i>. ἠλόησα, <i>pf. inus. ; pass. f</i>. ἀλοηθήσομαι, <i>ao</i>. ἠλοήθην, <i>pf</i>. ἠλόημαι)</font><br><b> 1</b> battre en grange, battre le grain, XÉN. <i>Œc. 18, 2 ;</i> PLAT. <i>Theag. 124</i> a, <i>etc. ;</i><br><b> 2</b> battre à coups redoublés, battre : γῆν χερσίν, IL. <i>9, 568,</i> la terre de ses mains ; <i>en mauv. part,</i> rouer de coups, SOPH. <i>fr. 21 ;</i> AR. <i>Th. 2, Ran. 149 ; d’où</i> abîmer, meurtrir, PLUT. <i>T. Gracch. 2, M. 327</i> a.<p><b>➼</b> <i>Part. ao</i>. ἀλοάσας <font color=\"brown\">[ᾱσ]</font> PHÉRÉCR. (<i>Bkk. 379</i>); <i>part. ao. pass</i>. ἀλοαθείς <font color=\"brown\">[ᾱθ]</font> TH. <i>C.P. 4, 6, 5. Prés. épq</i>. ἀλοιάω, THCR. <i>Idyl. 10, 48 ; impf. 3 sg</i>. ἀλοία, IL. <i>l. c</i>.</p><p><b>Étym</b>. <i>cf</i>. ἀλέω, ἄλευρον.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλοαω - ἀλοάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G249":"<h1>alogos</h1>\n<p>Strong n° 249 <i>Prononciation [al'-og-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>contraire à la raison, absurde</li>\n<li>qui n'a pas la raison, sans intelligence (animal)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄλογος</b> <b>ἄ·λογος, ος, ον :<br>   I</b> (λόγος, parole) :<br><b> 1</b> qui ne parle pas, PLAT. <i>Leg. 696</i> e ;<br><b> 2</b> qu’on ne peut exprimer par la parole, PLAT. <i>Theæt. 203</i> a ;<br><b> 3</b> ἄ. ἡμέρα, LUC. <i>Lex. 9,</i> jour où vaquent les tribunaux (<i>lat</i>. dies nefastus) ;<br><b>   II</b> (λόγος, raison) :<br><b> 1</b> sans raison, privé de raison ; τὰ ἄλογα ζῷα, PLUT. <i>M. 91</i> c ; DC. <i>55, 17 ;</i> ARTÉM. <i>2, 69 ; ou abs</i>. τὰ ἄλογα, XÉN. <i>Hier. 7, 3 ;</i> PLAT. <i>Prot. 321</i> b ; PLUT. <i>M. 662</i> f, <i>etc</i>. les êtres privés de raison, les animaux ;<br><b> 2</b> contraire à la raison, absurde, THC. <i>6, 85 ;</i> PLAT. <i>Rsp. 591</i> c ;<br><b> 3</b> qu’on ne peut se représenter par la raison, inintelligible, LYS. <i>177, 9 ;</i><br><b> 4</b> non guidé par la raison, irréfléchi, instinctif, PLAT. <i>Theæt. 201</i> c ;<br><b>   III</b> (λόγος, compte) :<br><b> 1</b> dont on ne peut rendre compte, <i>càd</i>. sans fondement, POL. <i>3, 15, 9 ; t. d’arithm</i>. irrationnel, EUCL. <i>Elem. def. 10, 1, 2 ; ou</i> sans proportion, sans commune mesure, ARSTT. <i>An. post. 1, 10, 3 ;</i><br><b> 2</b> que l’on ne peut calculer, à quoi l’on ne peut s’attendre, improbable, THC. <i>5, 105 ; ou</i> qui arrive contre toute attente, qui trompe l’attente, THC. <i>6, 46</i>.<br><i>● Cp</i>. -ώτερος, THC. <i>6, 46 ;</i> PLAT. <i>Gorg. 519</i> c, <i>etc.</i> <i>● Sup</i>. -ώτατος, PLAT. <i>Ap. 18</i> c, <i>Phil. 55</i> c, <i>etc</i>.<p><b>Étym</b>. ἀ, λόγος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-λογος - ἄλογος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G250":"<h1>aloe</h1>\n<p>Strong n° 250 <i>Prononciation [al-o-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aloès nom d'un arbre aromatique qui pousse dans l'est de l'Inde et la Chine, d'où est extrait un bois souple et amer, utilisé pour des fumigations, et pour embaumer des morts. L'arbre peut atteindre 40 mètres de hauteur, avec une circonférence de 4 mètres.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλόη</b> <b>ης (ἡ)</b> aloès, <i>plante,</i> DIOSC. <i>3, 25 ;</i> PLUT. <i>M. 141</i> f, <i>693</i> c.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλοη - ἀλόη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G251":"<h1>hals</h1>\n<p>Strong n° 251 <i>Prononciation [halce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἅλς ²</b> <b>ἁλός (ὁ)</b> <font color=\"brown\">[ᾰλο]</font> :<br><b>   I</b> sel, <i>particul. :</i><br><b> 1</b> bloc de sel, rocher de sel, HDT. <i>4, 181, 182, etc. ;</i> ARSTT. <i>Insomn. 53, 8 ;</i><br><b> 2</b> sel pour saupoudrer, <i>d’ord. plur</i>. OD. <i>11, 123 ; 23, 270 ;</i> HDT. <i>4, 53 ; 6, 119 ; 7, 30 ;</i> PLAT. <i>Conv. 177</i> b, <i>Tim. 60</i> e, <i>etc. ;</i> PLUT. <i>M. 684</i> e, <i>etc. ; en ce sens, sg</i>. IL. <i>9, 214 ;</i> PHILYLL. (<i>Com. fr. 2, 866</i>); AXION. (<i>Com. fr. 3, 535</i>); <i>prov</i>. οὐδ' ἅλα δοίης, OD. <i>17, 455 ;</i> THCR. <i>Idyl. 27, 60,</i> tu ne donnerais même pas un grain de sel ; <i>prov. c. symb. d’hospitalité :</i> <font color=\"blue\">ἅλας τε καὶ τράπεζαν</font>, ARCHIL. <i>96,</i> le sel et la table ; <i>cf</i>. DÉM. <i>400, 16 ; ou</i> ἅλες <i>seul,</i> DÉM. <i>401, 3 ;</i> ESCHN. <i>85 fin ;</i> τῶν ἁλῶν συγκατεδηδοκέναι μέδιμνον, PLUT. <i>M. 94</i> a, avoir mangé ensemble un boisseau de sel, <i>càd</i>. être de vieux amis ; <i>cf</i>. ARSTT. <i>Eud. 7, 2, 35 ;</i><br><b> 3</b> salines, DH. <i>2, 55 ;</i><br><b> 4</b> <i>fig</i>. sel d’une plaisanterie, d’un écrit, PLUT. <i>M. 685</i> a ;<br><b>   II</b> saumure, CALL. <i>fr. 50</i>.<p><b>Étym</b>. <i>R. indo-europ</i>. *seh₂l-, sel ; <i>cf. lat</i>. sāl.</p><b>ἅλς ¹</b> <b>ἁλός (ἡ)</b> <font color=\"brown\">[ᾰλο]</font> la mer, IL. <i>1, 141, etc. ;</i> OD. <i>2, 261, etc. ;</i> ἢ ἁλὸς ἢ ἐπὶ γῆς, OD. <i>12, 27,</i> et sur mer et sur terre ; <i>pléon</i>. πόντος ἁλός, IL. <i>21, 59 ;</i> THGN. <i>10 ; ou</i> ἁλὸς πέλαγος, OD. <i>5, 335 ;</i> HH. <i>Ap. 73 ;</i> EUR. <i>Tr. 88 ;</i> ἃλς πελαγία, ESCHL. <i>Pers. 427, etc</i>.<p><b>Étym</b>. <i>le sens de</i> « mer » <i>est poét., v</i>. ἅλς².</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλς - ἅλς</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td><font face=\"Georgia\">ἅλς</font> (hals) est un terme grec trouvé 0 fois dans la Bible.</td></tr>\n</table>","G252":"<h1>halukos</h1>\n<p>Strong n° 252 <i>Prononciation [hal-oo-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>saler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁλυκός</b> <b>ή, όν</b> <font color=\"brown\">[ᾰῠ]</font> salé, HPC. <i>Acut. 390 ;</i> AR. <i>Lys. 403 ;</i> PLAT. <i>Tim. 65</i> e ; PLUT. <i>M. 913</i> b.<p><b>➼</b> <i>● Cp</i>. -ώτερος, ARSTT. <i>Probl. 13, 25</i>.</p><p><b>Étym</b>. ἅλς.</p><b>Ἄλυκος ²</b> <b>ου (ἡ)</b> Alykos, <i>v. du Péloponnèse,</i> CALL. (E. BYZ. <i>v°</i> Ἄλυκος).<b>Ἄλυκος ¹</b> <b>ου (ὁ)</b> Alykos, <i>h</i>. HÉRÉAS (PLUT. <i>Thes. 32</i>).<b>Ἅλυκος ³</b> <b>ου (ὁ)</b> <i>fl. en Sicile</i>, PLUT. <i>Tim</i>. 34.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλυκος - ἁλυκός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G253":"<h1>alupoteros</h1>\n<p>Strong n° 253 <i>Prononciation [al-oo-pot'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>libéré de la peine ou du chagrin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-λυποτερος - ἄλυποτερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G254":"<h1>halusis</h1>\n<p>Strong n° 254 <i>Prononciation [hal'-oo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une chaîne, un lien par lequel le corps, ou une de ses parties (mains, pieds) est liée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄλυσις</b> <b>εως (ἡ)</b> agitation d’un malade, inquiétude, GAL.<p><b>Étym</b>. ἀλύω.</p><b>ἄλυσις ²</b> <i>v</i>. ἅλυσις<b>ἅλυσις</b> <i>ou</i> <b>ἄλυσις, εως (ἡ)</b> <font color=\"brown\">[ᾰῠ]</font> chaîne, HDT. <i>9, 74 ;</i> THC. <i>2, 76 ;</i> EUR. <i>Or. 984 ;</i> PLUT. <i>M. 829</i> a, <i>etc. ;</i> parure de femme, AR. <i>fr. 309</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλυσις - ἅλυσις</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Actes (4)</li>\n<li>Ephésiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G255":"<h1>alusiteles</h1>\n<p>Strong n° 255 <i>Prononciation [al-oo-sit-el-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans profit, préjudiciable, pernicieux, désavantageux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλυσιτελής</b> <b>ἀ·λυσιτελής, ής, ές</b> <font color=\"brown\">[ῡῐ]</font> désavantageux, XÉN. <i>Mem. 1, 7, 4, etc. ;</i> PLAT. <i>Crat. 417</i> d, <i>etc</i>.<br><i>● Sup</i>. -έστατος, ESCHN. <i>15, 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-λυσιτελης - ἀλυσιτελής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G256":"<h1>Alphaios</h1>\n<p>Strong n° 256 <i>Prononciation [al-fah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Alphée (Angl. Alphaeus) = « éphémère » peut-être Clopas de <a class=\"ref\" data-r=\"JHN19.25\">Jn 19.25</a>\n<ol>\n<li>père de Lévi le publicain, appelé Matthieu (<a class=\"ref\" data-r=\"MRK2.14\">Mr 2.14</a>)</li>\n<li>époux de l'une des Marie, père de Jacques le Mineur et de Joses</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αλφαιος</font> &lt; חלפי - <font face=\"Georgia\">Ἀλφαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G257":"<h1>halon</h1>\n<p>Strong n° 257 <i>Prononciation [hal'-ohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>surface en terre ou aire de battage, c.à.d le lieu dans le champ qui est aplani par un rouleau, avant d'extraire le grain par battage, aire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἅλων</b> <b>ωνος (ἡ)</b> <font color=\"brown\">[ᾰ]</font> <i>c</i>. ἅλως, ARSTT. <i>Vent. 3, etc. ;</i> SPT. <i>Gen. 50, 10, etc. ;</i> NT. <i>Matth. 3, 12 ; Luc. 3, 17</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλων - ἅλων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G258":"<h1>alopex</h1>\n<p>Strong n° 258 <i>Prononciation [al-o'-pakes]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un renard</li>\n<li>métaph. un homme rusé ou astucieux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀλώπηξ</b> <b>εκος (ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> renard, HDT. <i>2, 67 ;</i> ARSTT. <i>H.A. 8, 28, 7, etc. ; c. symbole de ruse (cf. franç</i>. un fin renard) DL. <i>2, 73 ; p. opp. au lion (symbole de courage</i>) PD. <i>I. 4, 79, etc. ;</i> PLUT. <i>Lys. c. Syll. 3 ;</i> ἀλώπεκος ἴχνεσι βαίνειν, SOL. (PLUT. <i>Sol. 30</i>) marcher sur les traces du renard, être rusé, fourbe ;<br><b>   II</b> <i>p. anal</i>. animaux divers :<br><b> 1</b> sorte d’oiseau (<i>sciurus</i> ou <i>pteromys volans</i>) ARSTT. <i>H.A. 1, 5, 10 ;</i><br><b> 2</b> renard de mer, <i>sorte de poisson,</i> ARSTT. <i>H.A. 6, 10, 4, etc. ;</i> OPP. <i>H. 3, 144 ;</i> EL. <i>V.H. 1, 5, etc. (cf</i>. ἀλωπεκίας) ;<br><b>   III</b> maladie des cheveux, CALL. <i>Dian. 79 ; cf</i>. ἀλωπεκία ;<br><b>   IV</b> <i>plur</i>. muscles des hanches, CLÉARQ. (ATH. <i>399</i> b).<p><b>➼</b> <i>Gén</i>. -ηκος, ANAN. <i>5 ; dat. pl</i>. -ήκεσσι, OPP. <i>C. 1, 433</i>.</p><p><b>Étym</b>. <i>indo-europ</i>. *h₂lop-, renard.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλωπηξ - ἀλώπηξ</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nom féminin</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G259":"<h1>halosis</h1>\n<p>Strong n° 259 <i>Prononciation [hal'-o-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une prise, capture, être pris</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἅλωσις</b> <b>εως</b>, <i>ion</i>. <b>ιος (ἡ) :<br>   I</b> prise, <i>d’où :</i><br><b> 1</b> prise, conquête, HDT. <i>1, 5, etc. ;</i> ESCHL. <i>Ag. 589 ;</i> PLAT. <i>Leg. 685</i> c, <i>etc. ;</i><br><b> 2</b> capture (d’un prisonnier), PLUT. <i>Num. 15 ;</i><br><b> 3</b> <i>t. de droit,</i> action de prendre en faute, PLAT. <i>Leg. 920</i> a ;<br><b>   II</b> moyen de prendre, SOPH. <i>Ph. 61</i>.<p><b>Étym</b>. <i>th</i>. ἁλω-, <i>v</i>. ἁλίσκομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αλωσις - ἅλωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G260":"<h1>hama</h1>\n<p>Strong n° 260 <i>Prononciation [ham'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en même temps, tout de suite, ensemble, tout à la fois, prep.</li>\n<li>ensemble avec, en même temps que</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁμᾶ</b> <i>v</i>. ἅμα.<b>ἁμᾷ</b> <i>v</i>. ἅμα.<b>ἅμα</b> <font color=\"brown\">[ᾰᾰ]</font> <i>adv. et prép. :</i><br><b>   I</b> <i>adv. :</i><br><b> 1</b> ensemble, tout à la fois : πάντες ἅ. IL. <i>1, 495 ;</i> POL. <i>23, 8, 3 ;</i> ἅμα πάντες, SPT. <i>Jos. 9, 2, etc</i>. tous ensemble ; ἅμα ἄμφω, HH. <i>Cer. 15,</i> tous deux ensemble ;<br><b> 2</b> <i>avec idée de temps,</i> en même temps ; <i>avec une conj. ou particule :</i> ἅμα καί, à la fois… et : ἅμα πρόσσω καὶ ὀπίσσω, IL. <i>3, 109</i> (il regarde) à la fois devant et derrière, <i>càd</i>. l’avenir et le passé ; ἅμα… τε καί, IL. <i>8, 64 ;</i> HH. <i>Merc. 46 ;</i> ἅμα τε… καί, IL. <i>1, 417 ;</i> θ' ἅμα… καί, IL. <i>24, 773 ;</i> θ' ἅμα καί, SOPH. <i>Ph. 772 ;</i> τε… θ' ἅμα, HÉS. <i>Th. 677 ;</i> τε καὶ… ἅμα, SOPH. <i>Ant. 281 ;</i> ἅμα τε… καὶ ἅμα, PLAT. <i>Gorg. 497</i> a, <i>m. sign. ;</i> καὶ… ἅμα, <i>avec un part. correspond qqf. au franç</i>. d’autant plus que, THC. <i>1, 2, 2 ; avec</i> δέ : ἅμα μῦθος ἔην, τετέλεστο δὲ ἔργον, IL. <i>19, 242,</i> la parole n’était pas plutôt dite que l’acte était accompli ; <i>avec</i> μὲν… δέ : ἅμα μὲν… ἅμα δέ, XÉN. <i>Hell. 3, 1, 2 ;</i> PLAT. <i>Phæd. 115</i> d, <i>etc.,</i> ἅμα μὲν… ἔτι δὲ καί, XÉN. <i>Cyr. 1, 4, 3,</i> tantôt… tantôt ; en partie… en partie ; <i>avec un part</i>. ἅ. εἰπὼν ἀνέστη, XÉN. <i>An. 3, 1, 47,</i> à peine avait-il parlé, qu’il se leva ; τῆς ἀγγελίας ἅ. καθ' ὁδὸν αὐτοῖς ῥηθείσης ἐπεϐοήθουν, THC. <i>2, 5,</i> la nouvelle leur étant parvenue tandis qu’ils étaient en route, ils continuèrent à se porter au secours (des leurs) ;<br><b>   II</b> <i>prép. avec le dat. :</i><br><b> 1</b> en même temps que, avec : ἅμ' ἠοῖ φαινομένηφιν, IL. <i>9, 682, ou</i> ἅμα ἕῳ, THC. <i>1, 48,</i> avec l’aurore ; ἅμ' ἡμέρᾳ, ἅμα τῇ ἡμέρᾳ (<i>v</i>. ἡμέρα), ἅμα τῇ ἡμέρῃ, HDT. <i>3, 86,</i> au point du jour ; <i>postér. avec le gén</i>. ἅμα τεττάρων, DS. <i>2, 529 L. Dind</i>. en même temps que quatre, avec quatre ; <i>avec un adv</i>. ἅμα πρωΐ, NT. <i>Matth. 20, 1,</i> dès le matin (<i>litt</i>. en même temps que le matin) ;<br><b> 2</b> en compagnie de, avec : ἅμα τινὶ στείχειν, IL. <i>16, 257,</i> marcher avec qqn ; <i>pléon</i>. ἅμα σύν, EUR. <i>Ion 717 ;</i> ἅμα μετά, PLAT. <i>Criti. 110</i> a, ensemble avec ;<br><b> 3</b> pareillement à, de même que : ἅμα πνοιῇσ' ἀνέμοιο, OD. <i>1, 98,</i> comme le souffle du vent.<p><b>➼</b> <i>Dor</i>. ἁμᾶ <i>ou</i> ἁμᾷ, PD. <i>O. 3, 22 ; P. 3, 36 ; N. 5, 11 ; 7, 78 ;</i> AR. <i>Lys. 1316 ;</i> THCR. <i>Idyl. 9, 4 ; 11, 39. Chez les écriv. byzantins, qqf. avec le gén</i>.</p><p><b>Étym</b>. <i>probabl. degré zéro de la R. indo-europ</i>. *sem-, un ; <i>cf</i>. εἷς, ὁμός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμα - ἅμα</font>\n<br><br>particule primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G261":"<h1>amathes</h1>\n<p>Strong n° 261 <i>Prononciation [am-ath-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non instruit, ignorant, mal instruit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμαθής</b> <b>ἀ·μαθής, ής, ές</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b>   I</b> qui ne sait pas :<br><b> 1</b> ignorant, ATT. ; ἀ. τινος, THC. <i>4, 41 ;</i> EUR. <i>Or. 417 ;</i> περί τινος, PLAT. <i>Eryx. 394</i> e ; πρός τι, PLAT. <i>Leg. 679</i> d ; τι, PLAT. <i>Lach. 194</i> d, ignorant de qqe ch., au sujet de qqe ch. ; <i>avec un n. de chose :</i> ὄνειδος ἀμαθές, EUR. <i>I.A. 999,</i> un reproche ignorant, <i>càd</i>. provenant de l’ignorance des faits (<i>sel. d’autres,</i> reproche grossier <i>ou</i> reproche imprévu) ;<br><b> 2</b> <i>p. suite,</i> sot, stupide, PLAT. <i>Ap. 22</i> e ; <i>joint à</i> βδελυρός, AR. <i>Eq. 193 ; p. opp. à</i> δεξιός, THC. <i>3, 82, etc. ;</i><br><b> 3</b> non civilisé, grossier, HDT. <i>4, 46 ; en parl. d’animaux,</i> sauvage, ARSTT. <i>H.A. 1, 1, 32 ; en parl. de choses abstraites ;</i> ἀ. ῥώμη, EUR. <i>fr. 732 Nauck,</i> force brutale ;<br><b>   II</b> dont on ne sait rien, inconnu, EUR. <i>Ion 916</i>.<br><i>● Cp</i>. -έστερος, THC. <i>3, 37 ;</i> XÉN. <i>Mem. 1, 2, 49, etc.</i> <i>● Sup</i>. -έστατος, HDT. <i>4, 46 ;</i> THC. <i>6, 40 ;</i> XÉN. <i>Mem. 3, 6, 17, etc. ;</i> AR. <i>Pax 1230, etc. ;</i> AND. <i>20, 1, etc</i>.<p><b>➼</b> <i>Qqf. contracté par crase poét. avec</i> μή : μἀμαθής, EUR. <i>Suppl. 421 ;</i> μἀμαθεῖς, EUR. <i>Tr. 981</i>.</p><p><b>Étym</b>. ἀ, μανθάνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μαθης - ἀμαθής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G262":"<h1>amarantinos</h1>\n<p>Strong n° 262 <i>Prononciation [am-ar-an'-tee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>incorruptible, imputrescible, qui ne se flétrit pas</li>\n<li>couronne composée d'amarante, fleur qui ne se fane jamais\n<ol type=\"a\">\n<li>symbole de perpétuité et d'immortalité</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμαράντινος</b> <b>η, ον</b> <font color=\"brown\">[ᾰμᾰ]</font> :<br><b> 1</b> d’amarante, PHILSTR. <i>741 ;</i><br><b> 2</b> d’immortelles, NT. <i>1Petr. 5, 4</i>.<p><b>Étym</b>. ἀμάραντος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μαραντινος - ἀμαράντινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G263":"<h1>amarantos</h1>\n<p>Strong n° 263 <i>Prononciation [am-ar'-an-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ne se fane pas : fleur d'amarante</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμάραντος</b> <b>ἀ·μάραντος, ος, ον</b> <font color=\"brown\">[ᾰμᾰ]</font> :<br><b> 1</b> qui ne se flétrit pas, LUC. <i>Dom. 9 ;</i> SPT. <i>Sap. 6, 12 ;</i> NT. <i>1Petr. 1, 4 ;</i><br><b> 2</b> ὁ ἀμ. amarante <i>ou</i> immortelle, <i>plante,</i> DIOSC. <i>3, 9 ; 4, 55 ; 4, 57</i>.<p><b>Étym</b>. ἀ, μαραίνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μαραντος - ἀμάραντος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G264":"<h1>hamartano</h1>\n<p>Strong n° 264 <i>Prononciation [ham-ar-tan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>péché = « erreur, faux état d'esprit »\n<ol>\n<li>ne pas participer</li>\n<li>manquer la marque</li>\n<li>errer d'ou se tromper, commettre une faute, faillir, être fautif,</li>\n<li>manquer le chemin de la droiture et de l'honneur, faire le mal</li>\n<li>s'éloigner de la loi de Dieu, violer cette loi, pécher</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁμαρτάνω</b> <font color=\"darkgreen\">(<i>f</i>. ἁμαρτήσομαι, <i>ao.2</i> ἥμαρτον, <i>pf</i>. ἡμάρτηκα ; <i>pass. ao</i>. ἡμαρτήθην, <i>pf</i>. ἡμάρτημαι)</font><br><b>   I</b> <i>au pr. :</i><br><b> 1</b> manquer le but, IL. <i>5, 287 ;</i> ESCHL. <i>fr. 179, etc. ; avec un gén. :</i> ἁ. σκοποῦ, ANT. <i>124, 26,</i> manquer le but ; τινὸς ἁ. IL. <i>10, 372,</i> manquer qqn ;<br><b> 2</b> <i>p. suite</i> dévier, s’égarer : ἁ. τῆς ὁδοῦ, AR. <i>Pl. 961,</i> se tromper de chemin, s’égarer ;<br><b>   II</b> <i>fig. :</i><br><b> 1</b> se tromper, se méprendre, <i>avec un gén</i>. ἁμαρτάνειν, THC. <i>1, 33 ; 6, 92, etc</i>. avoir une fausse opinion, faire fausse route ; ἁ. τἀληθέος, HDT. <i>7, 139,</i> s’écarter de la vérité ; <i>avec l’acc. seul,</i> HDT. <i>7, 139 ;</i><br><b> 2</b> ne pas obtenir : ἁ. τί τινος, SOPH. <i>Ph. 231,</i> ne pas obtenir qqe ch. de qqn ;<br><b> 3</b> être privé de, <i>gén</i>. OD. <i>7, 292 ; d’où</i> perdre, <i>gén. :</i> ὀπωπῆς ἁμαρτάνειν, OD. <i>9, 512,</i> perdre la vue ;<br><b> 4</b> manquer de faire, négliger, <i>gén</i>. IL. <i>24, 68 ;</i> ESCHL. <i>Ag. 213 ;</i><br><b> 5</b> commettre une faute, faillir, pécher, IL. <i>9, 501 ;</i> ESCHL. <i>Pr. 260 ;</i> SOPH. <i>El. 1207, etc. ;</i> THC. <i>1, 21 ;</i> ἁ. τι, OD. <i>22, 154 ;</i> ESCHL. <i>Suppl. 915 ;</i> SOPH. <i>Aj. 1096 ;</i> AR. <i>Pl. 474 ;</i> περί τι, XÉN. <i>An. 3, 2, 20 ;</i> PLAT. <i>Rsp. 334</i> c ; περί τινος, XÉN. <i>Hell. 1, 7, 27 ;</i> PLAT. <i>Leg. 891</i> e ; DÉM. <i>501, 2 ;</i> ἐπί τινι, ANT. <i>140, 13 ;</i> ἐπί τι, ARSTT. <i>Nic. 4, 5, 3 ;</i> ἔν τινι, THC. <i>1, 42, etc. ;</i> PLAT. <i>Rsp. 340</i> d ; <i>ou</i> τινι, EUR. <i>Tr. 1123 ;</i> PLAT. <i>Gorg. 489</i> b, faillir en qqe ch. ; ἁ. εἴς τινα, HDT. <i>1, 138 ;</i> THC. <i>1, 38 ;</i> SOPH. <i>O.C. 968 ;</i> περί τινα, ANT. <i>121, 41 ;</i> τι περί τινα, XÉN. <i>An. 3, 2, 20,</i> commettre une faute à l’égard de qqn ; ἁμαρτίαν ἁμ. ἔς τινα, EUR. <i>Hipp. 320 ;</i> ἁμάρτημα περί τινα ἁμ. PLAT. <i>Leg. 730</i> a, commettre une faute à l’égard de qqn, envers qqn ; <i>avec un part</i>. se tromper en…, avoir tort de…, EUR. <i>Or. 1630 (mais le part. marque qqf. une action simultanée :</i> ἥμαρτε χρηστὰ μωμένη, SOPH. <i>Tr. 1136,</i> elle s’est trompée voulant bien faire) <i>etc. ; au pass</i>. εἰ ἡμάρτηται, THC. <i>3, 56,</i> s’il y a eu faute ; ἁμαρτάνεται περί τι, PLAT. <i>Leg. 759</i> c, on se trompe en qqe ch., on fait une faute ; τὰ ἡμαρτημένα, SOPH. <i>O.C. 439, 1269 ;</i> EUR. <i>Tr. 1028, etc</i>. les fautes commises ; τὰ περὶ τὴν πόλιν ἁμαρτανόμενα, XÉN. <i>Mem. 1, 2, 9,</i> les fautes que l’on commet envers l’État ; τὰ περί τι εἰς τὰ θεῖα ἁμαρτανόμενα, PLAT. <i>Leg. 759</i> c, les fautes que l’on commet en qqe ch. à l’égard de la religion, les manquements en matière de religion ; ἡμαρτημέναι πολιτεῖαι, PLAT. <i>Rsp. 449</i> a ; ARSTT. <i>Pol. 3, 1, 9, etc</i>. États mal administrés<br><font color=\"darkblue\"><b>➼</b> <i>Fut</i>. ἁμαρτήσω, CHIL. (STOB. <i>Fl. 3, 79), surt. d’usage réc</i>. DC. <i>59, 20 ;</i> GAL. <i>7, 653 ; 13, 755 ;</i> NT. <i>Matth. 18, 21. Ao.1</i> ἡμάρτησα, EMPÉD. <i>372 Stein ;</i> SPT. <i>1Reg. 19, 4 ;</i> ANTH. <i>7, 339 ;</i> DS. <i>2, 14, etc. Ao.2 poét</i>. ἅμαρτον <font color=\"brown\">[ᾰμ]</font> IL. <i>4, 491, etc. ;</i> PD. <i>N. 7, 37 ; opt. poét. 1 sg</i>. ἁμάρτοιν, CRAT. (<i>Com. fr. 2, 47</i>); <i>ao.2 épq</i>. ἤμϐροτον (<i>p</i>. ἥμαρτον, *ἥμρατον, *ἥμροτον, ἥμϐροτον) <i>seul. indic</i>. IL. <i>5, 287, etc. ;</i> OD. <i>21, 425, etc. ;</i> A. RH. <i>2, 623</i>.</font><p><font color=\"purple\"><b>Étym</b>. <i>R. indo-europ</i>. *h₂mert-, manquer ; <i>cf</i>. νημερτής.</font>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμαρτανω - ἁμαρτάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n44 fois dans 37 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (4)</li>\n<li>Jean (4)</li>\n<li>Actes (1)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (7)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (10)</li>\n</ul>\n</td></tr>\n</table>","G265":"<h1>hamartema</h1>\n<p>Strong n° 265 <i>Prononciation [ham-ar'-tay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>péché, mauvaise action, erreur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁμάρτημα</b> <b>ατος (τὸ)</b> <font color=\"brown\">[ᾰμ]</font> :<br><b> 1</b> erreur, faute, THC. <i>2, 65 ;</i> SOPH. <i>Ant. 1261 ;</i> PLAT. <i>Pol. 296</i> b, <i>etc. ; p. opp. à</i> ἀδίκημα ;<br><b> 2</b> infirmité, maladie, PLAT. <i>Gorg. 479</i> a.<p><b>Étym</b>. ἁμαρτάνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμαρτημα - ἁμάρτημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G266":"<h1>hamartia</h1>\n<p>Strong n° 266 <i>Prononciation [ham-ar-tee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>équivalent à </li>\n<li>ce qui est mal, péché une offense, violation de la loi divine en pensée ou en actes</li>\n<li>collectivement, les péchés commis par une ou plusieurs personnes</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁμαρτία</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾰμ]</font> erreur, faute, ESCHL. <i>Pr. 9, Ag. 1198, etc. ;</i> SOPH. <i>Ph. 1248 ;</i> EUR. <i>Hipp. 320 ;</i> THC. <i>1, 32 ;</i> PLAT. <i>Rsp. 379</i> d, <i>etc</i>.<p><b>Étym</b>. ἁμαρτάνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμαρτια - ἁμαρτία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n173 fois dans 150 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (6)</li>\n<li>Luc (11)</li>\n<li>Jean (17)</li>\n<li>Actes (8)</li>\n<li>Romains (48)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (25)</li>\n<li>Jacques (6)</li>\n<li>1 Pierre (6)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (17)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G267":"<h1>amarturos</h1>\n<p>Strong n° 267 <i>Prononciation [am-ar'-too-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans témoin ou témoignage, non attesté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμάρτυρος</b> <b>ἀ·μάρτυρος, ος, ον</b> <font color=\"brown\">[ῠ]</font> sans témoin, THC. <i>2, 41 ;</i> DÉM. <i>502, 20, etc</i>.<p><b>Étym</b>. ἀ, μάρτυρ.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μαρτυρος - ἀμάρτυρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G268":"<h1>hamartolos</h1>\n<p>Strong n° 268 <i>Prononciation [ham-ar-to-los']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dévoué au péché, un pécheur, une pécheresse\n<ol type=\"a\">\n<li>non libéré du péché</li>\n<li>spécialement méchant\n<ol>\n<li>spécificité des hommes atteints de certains vices ou crimes\n<ol type=\"a\">\n<li>collecteurs de taxes, païens</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁμαρτωλός</b> <b>ός, όν</b> <font color=\"brown\">[ᾰμ]</font> :<br><b> 1</b> qui fait fausse route, qui se trompe, ARSTT. <i>Nic. 2, 9, 4 ;</i> PLUT. <i>M. 25</i> c ;<br><b> 2</b> qui est en faute, coupable, pécheur, SPT. <i>Gen. 13, 13 ; Num. 32, 14 ; Sir. 10, 23 ; 1 Macc. 1, 10 ;</i> ὁ ἁμ. le pécheur, SPT. <i>Num. 16, 37, etc. ;</i> PLUT. <i>M. 25</i> c ; NT. <i>Luc. 7, 37 ; Marc. 8, 39</i>.<br><i>● Cp</i>. -ότερος, ARSTT. <i>l. c</i>.<p><b>➼</b> <i>Fém</i>. -ή, <i>barbarisme d’un Scythe,</i> AR. <i>Th. 1111</i>.</p><p><b>Étym</b>. ἁμαρτάνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμαρτωλος - ἁμαρτωλός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 45 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (6)</li>\n<li>Luc (18)</li>\n<li>Jean (4)</li>\n<li>Romains (4)</li>\n<li>Galates (2)</li>\n<li>1 Timothée (2)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G269":"<h1>amachos</h1>\n<p>Strong n° 269 <i>Prononciation [am'-akh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>auquel on ne peut résister, invincible</li>\n<li>non agressif, non belliqueux,</li>\n<li>s'abstenant de conflit, pacifique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄμαχος</b> <b>ἄ·μαχος, ος, ον</b> <font color=\"brown\">[μᾰ]</font> :<br><b>   I</b> qui ne combat pas, <i>càd. :</i><br><b> 1</b> qui ne prend pas part au combat, XÉN. <i>Cyr. 4, 1, 16, etc. ;</i><br><b> 2</b> non belliqueux, pacifique, ESCHL. <i>Pers. 855 ; d’où</i> non querelleur, NT. <i>1Tim. 3, 3 ; Tit. 3, 2 ;</i><br><b>   II</b> qu’on ne peut combattre, invincible, <i>en parl. de pers</i>. HDT. <i>5, 3 ;</i> ESCHL. <i>Pers. 855, etc. ;</i> SOPH. <i>Ant. 799, etc. ; en parl. de villes,</i> imprenable, HDT. <i>1, 84 ; en parl. de choses,</i> irrésistible (flot, ESCHL. <i>Pers. 90 ;</i> mal, PD. <i>P. 2, 76 ;</i> haine, EUR. <i>Rhes. 456, etc</i>.); <i>p. suite,</i> dont on ne peut venir à bout : ἄμαχόν (ἐστι) <i>avec l’inf</i>. PD. <i>O. 13, 13,</i> il est impossible de, <i>etc</i>.<br><i>● Cp</i>. -ώτερος, AR. <i>Lys. 1014</i>. <i>● Sup</i>. -ώτατος, THGN. <i>1157 ;</i> LUC. <i>Char. 8</i>.<p><b>Étym</b>. ἀ, μάχη.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μαχος - ἄμαχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G270":"<h1>amao</h1>\n<p>Strong n° 270 <i>Prononciation [am-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>moissonner, faucher, tondre, couper les tiges</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμάω</b> <b>ἀμάω-ῶ</b> <font color=\"darkgreen\">(<i>impf</i>. ἤμων, <i>f</i>. ἀμήσω, <i>ao</i>. ἤμησα, <i>pf. inus. ; pass. ao</i>. ἠμήθην, <i>pf. inus</i>.)</font> <font color=\"brown\">[α]</font> :<br><b> 1</b> moissonner, IL. <i>18, 551 ;</i> HÉS. <i>O. 478 ;</i> ESCHL. <i>Ag. 1044 ; p. anal</i>. faucher, moissonner sur le champ de bataille, A. RH. <i>3, 1187 ; p. ext</i>. couper, <i>en gén</i>. THCR. <i>Idyl. 11, 73 ;</i><br><b> 2</b> <i>p. suite,</i> récolter, <i>acc</i>. OD. <i>9, 135 ;</i> HDT. <i>6, 28 ;</i> AR. <i>Eq. 392 ; fig</i>. ἀ. ἐλευθερίαν, PLUT. <i>M. 210</i> b, récolter les fruits de la liberté ; <i>cf</i>. CALL. <i>Cer. 137 ;</i><br><b> 3</b> recueillir, amasser, <i>acc</i>. IL. <i>24, 451 ;</i> ANTH. <i>7, 241 ;</i><br><b>Moy. ἀμάομαι-ῶμαι</b> <font color=\"darkgreen\">(<i>f</i>. ἀμήσομαι)</font><br><b> 1</b> moissonner, A. RH. <i>1, 688 ;</i> Q. SM. <i>14, 199 ; d’où</i> couper, <i>en gén</i>. ANTH. <i>4, 1, 26 ;</i><br><b> 2</b> recueillir, amasser, OD. <i>9, 247 ;</i> HÉS. <i>Th. 599 ;</i> A. RH. <i>1, 1305</i>.<p><b>➼</b> <i>Act. prés. opt. 2 sg</i>. ἀμῷς, THGN. <i>107 ; 3 plur</i>. ἀμῷεν, OD. <i>9, 135 ; inf. épq</i>. ἀμάειν <font color=\"brown\">[μᾱ]</font> HÉS. <i>O. 392 ; part. épq</i>. ἀμώων, THCR. <i>Idyl. 10, 51 ;</i> ANTH. <i>9, 362 ;</i> A. RH. <i>3, 1382 ; dat. pl. dor</i>. ἀμάντεσσι (<i>vulg</i>. ἀμώντεσσι) THCR. <i>Idyl. 10, 16. Ao. dor. sbj. 3 sg</i>. ἀμάσῃ <font color=\"brown\">[μᾱ]</font> CALL. <i>Cer. 137 ; part</i>. ἀμάσας <font color=\"brown\">[μᾱ]</font> THCR. <i>Idyl. 11, 73. Pass. ao</i>. ἠμήθην, NIC. <i>Al. 216. Moy. f. dor</i>. ἀμάσομαι <font color=\"brown\">[μᾱ]</font> SOPH. <i>fr. 550 ; ao</i>. ἀμασάμην <font color=\"brown\">[μᾱ]</font> ANTH. <i>7, 446</i>.</p><p><b>Étym</b>. <i>R. indo-europ</i>. *h₂meh₁-, faucher ; <i>cf. lat</i>. metō, messis.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμαω - ἀμάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G271":"<h1>amethustos</h1>\n<p>Strong n° 271 <i>Prononciation [am-eth'-oos-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>améthyste, une pierre précieuse de couleur pourpre et violet</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμέθυστος</b> <b>ἀ·μέθυστος, ος, ον :<br>   I</b> sans ivresse : ἡμέρα ἀ. PLUT. <i>M. 464</i> c, jour où l’on ne s’enivre pas ;<br><b>   II</b> qui dissipe l’ivresse : ἡ ἀ. :<br><b> 1</b> sorte d’herbe employée contre l’ivresse, PLUT. <i>M. 647</i> b ;<br><b> 2</b> améthyste, pierre précieuse qui passait pour préserver de l’ivresse, DP. <i>1122 ;</i> ANTH. <i>5, 205 ; 9, 748, etc</i>.<p><b>Étym</b>. ἀ, μεθύω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμεθυστος - ἀμέθυστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G272":"<h1>ameleo</h1>\n<p>Strong n° 272 <i>Prononciation [am-el-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prendre soin de, négliger, rester indifférent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμελέω</b> <b>ἀμελέω-ῶ</b> <font color=\"darkgreen\">(<i>f</i>. ήσω, <i>ao</i>. ἠμέλησα, <i>pf</i>. ἠμέληκα)</font> ne pas s’inquiéter, négliger : τινος, IL. <i>8, 330, etc. ;</i> HDT. <i>2, 121, etc. ;</i> THC. <i>3, 40, etc. ;</i> XÉN. <i>Ages. 7, 3, etc. ; rar</i>. ἐπί τινι, SOPH. <i>El. 237,</i> négliger qqn ; <i>rar</i>. τι, HDT. <i>7, 163,</i> négliger qqe ch. ; <i>avec l’inf</i>. ἀ. ποιεῖν, HDT. <i>2, 66 ;</i> PLAT. <i>Phæd. 98</i> d, <i>Leg. 944</i> c, <i>etc</i>. négliger de faire ; <i>abs</i>. être négligent, insouciant, HÉS. <i>O. 398 ;</i> ESCHL. <i>Eum. 86, etc. ; au pass</i>. être négligé, délaissé ; ὑπό τινος, THC. <i>1, 68 ;</i> τινι, EUR. <i>I.A. 1094,</i> par qqn ; <i>abs</i>. XÉN. <i>Cyr. 7, 5, 75, etc</i>.<p><b>Étym</b>. ἀμελής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμαλεω - ἀμελέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G273":"<h1>amemptos</h1>\n<p>Strong n° 273 <i>Prononciation [am'-emp-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>innocent, ne méritant pas de censure, libre de faute ou défaut, à l'abri du blâme, à qui rien n'est reproché</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄμεμπτος</b> <b>ἄ·μεμπτος, ος, ον :<br> 1</b> irréprochable, EUR. <i>I.A. 1158, etc. ;</i> DÉM. <i>300, 17 ;</i> ἄ. τι, MÉN. <i>4, 224 Meineke ;</i> πρός τι, ESCHL. <i>Suppl. 629 ;</i> τινος, ESCHL. <i>Pers. 692,</i> en qqe ch. ; ὑπό τινος, XÉN. <i>Ages. 6, 8,</i> qui ne mérite pas de reproches de qqn ; <i>d’où</i> excellent, parfait : ἄ. δεῖπνον, XÉN. <i>Conv. 2, 2,</i> repas excellent ;<br><b> 2</b> qui ne fait pas de reproche : ἄμεμπτόν τινα ποιεῖσθαι <i>ou</i> ποιεῖν, XÉN. <i>Cyr. 4, 5, 52 ; 8, 4, 28,</i> ôter à qqn tout motif de reproche, satisfaire qqn.<br><i>● Cp</i>. -ότερος, PLUT. <i>Ages. 5, M. 610</i> d ; <i>sup</i>. -ότατος, ANTH. <i>12, 22, 6</i>.<p><b>Étym</b>. ἀ, μέμφομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μεμπτος - ἄμεμπτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Philippiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G274":"<h1>amemptos</h1>\n<p>Strong n° 274 <i>Prononciation [am-emp'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>innocent, ne donne lieu à aucune censure, d'une manière irréprochable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμέμπτως</b> <i>adv. :</i><br><b> 1</b> de manière à ne mériter aucun blâme, ESCHL. <i>Suppl. 269 ;</i> SOPH. <i>Ph. 1465 ;</i> XÉN. <i>Cyr. 7, 3, 10 ;</i><br><b> 2</b> sans faire de reproche, <i>d’où</i> avec satisfaction, avec plaisir, XÉN. <i>Cyr. 4, 2, 37</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μεμπτως - ἀμέμπτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G275":"<h1>amerimnos</h1>\n<p>Strong n° 275 <i>Prononciation [am-er'-im-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>libéré de l'anxiété, sans aucun souci</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμέριμνος</b> <b>ἀ·μέριμνος, ος, ον :<br> 1</b> qu’on néglige, dont on ne s’inquiète pas, SOPH. <i>Aj. 1206 ;</i><br><b> 2</b> sans inquiétude, ANTH. <i>9, 359 ;</i> HDN <i>2, 4, 3 ; 3, 7, 11 ;</i> τὸ ἀμέριμνον, l’absence de soucis, la tranquillité, HDN <i>1, 6, 26, etc. ;</i><br><b> 3</b> qui dissipe toute inquiétude, ANTH. <i>11, 24, 4</i>.<br><i>● Cp</i>. -ότερος, ANTH. <i>11, 24</i>.<p><b>Étym</b>. ἀ, μέριμνα.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μεριμνος - ἀμέριμνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G276":"<h1>ametathetos</h1>\n<p>Strong n° 276 <i>Prononciation [am-et-ath'-et-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ne peut être transféré, fixé, inaltérable, immuable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμετάθετος</b> <b>ἀ·μετάθετος, ος, ον</b>, immuable, POL. <i>2, 32, 5, etc. ;</i> DS. <i>1, 23, etc. ;</i> PLUT. <i>M. 675</i> b ; SPT. <i>3Macc. 5, 1, etc</i>.<p><b>Étym</b>. ἀ, μετατίθημι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μεταθετος - ἀμετάθετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G277":"<h1>ametakinetos</h1>\n<p>Strong n° 277 <i>Prononciation [am-et-ak-in'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ne peut être déplacé, inamovible</li>\n<li>métaph. fermement persistant, inébranlable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμετακίνητος</b> <b>ἀ·μετακίνητος, ος, ον</b> <font color=\"brown\">[ῑ]</font> immuable, immobile, PLAT. <i>Ep. 343</i> a ; ARSTT. <i>Phys. 4, 4, 18 ;</i> DH. <i>8, 74, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μετακινητος - ἀμετακίνητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G278":"<h1>ametameletos</h1>\n<p>Strong n° 278 <i>Prononciation [am-et-am-el'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans repentance, sans regret</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμεταμέλητος</b> <b>ἀ·μεταμέλητος, ος, ον :<br> 1</b> dont on ne se repent pas, que l’on ne regrette pas, PLAT. <i>Leg. 866</i> e, <i>Tim. 59</i> d ; POL. <i>24, 12, 11, etc. ;</i><br><b> 2</b> qui n’éprouve aucun regret, ARSTT. <i>Nic. 7, 7, 2</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μεταμελητος - ἀμεταμέλητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G279":"<h1>ametanoetos</h1>\n<p>Strong n° 279 <i>Prononciation [am-et-an-o'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>n'admettant aucun changement de son esprit, impénitent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμετανόητος</b> <b>ἀ·μετανόητος, ος, ον :<br> 1</b> qui ne cause pas de regret, LUC. <i>Abd. 11 ;</i><br><b> 2</b> qui ne se repent pas, NT. <i>Rom. 2, 5 ;</i> PHIL. <i>2, 410</i>.<p><b>Étym</b>. ἀ, μετανοέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μετανοητος - ἀμετανόητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G280":"<h1>ametros</h1>\n<p>Strong n° 280 <i>Prononciation [am'-et-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans mesure, immense</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄμετρος</b> <b>ἄ·μετρος, ος, ον :<br> 1</b> sans mesure, qui ne peut pas être mesuré, <i>p. opp. à</i> μετρητός, PLAT. <i>Leg. 820</i> c ;<br><b> 2</b> <i>p. suite,</i> immense, innombrable, XÉN. <i>An. 3, 2, 16, etc. ;</i> SIM. (ATH. <i>680</i> d), <i>etc. ;</i><br><b> 3</b> immodéré, XÉN. <i>Ep. 1, 8 ;</i> PLAT. <i>Ep. 354</i> d ; <i>adv</i>. ἄμετρα, sans mesure, à l’excès, NT. <i>2Cor. 10, 13, etc. ;</i><br><b> 4</b> disproportionné, PLAT. <i>Tim. 87</i> e ;<br><b> 5</b> sans mesure prosodique, en prose, <i>p. opp. à</i> ἔμμετρος, ARSTT. <i>Poet. 9, 2 ;</i> DH. <i>Comp. 3 ;</i><br><b> 6</b> non conforme à la mesure (vers) PLUT. <i>M. 80</i> d.<br><i>● Cp</i>. -ότερος, PLAT. <i>Phil. 65</i> d (<i>var</i>. -ώτερος).<p><b>Étym</b>. ἀ, μέτρον.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μετρος - ἄμετρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G281":"<h1>amen</h1>\n<p>Strong n° 281 <i>Prononciation [am-ane']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ferme\n<ol type=\"a\">\n<li>métaph. fidèle</li>\n</ol>\n</li>\n<li>véritablement, amen\n<ol type=\"a\">\n<li>au début d'un discours - sûrement, vraiment, en vérité</li>\n<li>à la fin - ainsi soit-il, que ceci s'accomplisse.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμην</font> &lt; אמן - <font face=\"Georgia\">ἀμήν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n130 fois dans 104 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (31)</li>\n<li>Marc (13)</li>\n<li>Luc (7)</li>\n<li>Jean (50)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G282":"<h1>ametor</h1>\n<p>Strong n° 282 <i>Prononciation [am-ay'-tore]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>orphelin à la naissance</li>\n<li>privé de sa mère</li>\n<li>né de mère inconnue</li>\n<li>non digne du nom de mère</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμήτωρ</b> <b>ἀ·μήτωρ, ορος (ὁ, ἡ) :<br> 1</b> né d’une mère inconnue, HDT. <i>4, 154 ;</i> EUR. <i>Ion 109 ;</i> PLAT. <i>Conv. 180</i> d ;<br><b> 2</b> né d’une mère indigne, EUR. <i>Ion 837 ;</i><br><b> 3</b> μήτηρ ἀ. SOPH. <i>El. 1154,</i> mère qui n’en est pas une.<p><b>➼</b> <i>Dor</i>. ἀμάτωρ <font color=\"brown\">[μᾱ]</font> EUR. <i>Ph. 570</i>.</p><p><b>Étym</b>. ἀ, μήτηρ.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μητωρ - ἀμήτωρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G283":"<h1>amiantos</h1>\n<p>Strong n° 283 <i>Prononciation [am-ee'-an-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non souillé, sans souillure\n<ol type=\"a\">\n<li>libre de ce qui, par la nature des choses, est déformé, souillé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμίαντος</b> <b>ἀ·μίαντος, ος, ον :<br> 1</b> sans souillure, pur : ὕδωρ ἀ. THGN. <i>447,</i> eau limpide ; ἀ. περί τινος, PLAT. <i>Leg. 777</i> e, pur de qqe souillure ; ἡ ἀ. ESCHL. <i>Pers. 578 (sel. d’autres avec</i> ἅλς <i>exprimé</i>) la mer (l’eau lustrale par excellence, qui enlève les souillures et ne peut être souillée) ;<br><b> 2</b> incorruptible, DH. <i>2, 75 ;</i><br><b> 3</b> ὁ ἀ. (λίθος) DIOSC. <i>5, 156,</i> l’amiante, <i>sorte de pierre</i>.<p><b>Étym</b>. ἀ, μιαίνω.</p><b>Ἀμίαντος</b> <b>Ἀ·μίαντος, ου (ὁ)</b> Amiantos, <i>h</i>. HDT. <i>6, 127 ;</i> AND. <i>9, 25</i>.<p><b>Étym</b>. <i>v</i>. ἀμίαντος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μιαντος - ἀμίαντος</font>\n<br><br>Voir définition  TDNT – , , </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Hébreux (2</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G284":"<h1>Aminadab</h1>\n<p>Strong n° 284 <i>Prononciation [am-ee-nad-ab']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Aminadab (Angl. Amminadab) = « un du prince du peuple »\n<ol><li>un ancêtre de Christ</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αμιναδαβ</font> &lt; עמינדב - <font face=\"Georgia\">Ἀμιναδάβ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G285":"<h1>ammos</h1>\n<p>Strong n° 285 <i>Prononciation [am'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sable, sol sablonneux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄμμος ²</b> <i>éol. c</i>. ἡμέτερος, DYSC. <i>Pron. 144</i> a.<b>ἄμμος ³</b> <i>éol. c</i>. ἡμέτερος, DYSC. <i>Pron</i>. 144a.<b>ἄμμος ¹</b> <b>ου (ἡ) :<br> 1</b> sable, PLAT. <i>Phæd. 110</i> a ; ARSTT. <i>H.A. 4, 1, etc. ;</i> PLUT. <i>Fab. 6, etc. ;</i><br><b> 2</b> arène sablée, XÉN. <i>Mem. 3, 3, 6 ;</i><br><b> 3</b> terre sulfureuse, STR.<p><b>Étym</b>. <i>emprunt à un substrat pré-indo-europ. ; cf</i>. ψάμμος, ψάμαθος <i>et</i> ἄμαθος.</p><b>Ἄμμος</b> <b>ου (ἡ)</b> Ammos, <i>litt</i>. « le sable » <i>contrée de Carie,</i> ESCHN. <i>679</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμμος - ἄμμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G286":"<h1>amnos</h1>\n<p>Strong n° 286 <i>Prononciation [am-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un agneau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμνός</b> <b>οῦ (ὁ, ἡ)</b> agneau, AR. <i>Av. 1559, etc. ; dans les Livres saints, en parl. de J.C. l’agneau sans tache,</i> NT. <i>Ap. 8, 33 ; Joh. 1, 29, 36 ; 1Petr. 1, 19 ;</i> ἡ ἀ. agneau femelle, agnelle, THCR. <i>Idyl. 5, 144, etc. ;</i> ANTH. <i>5, 205</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμνος - ἀμνός</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G287":"<h1>amoibe</h1>\n<p>Strong n° 287 <i>Prononciation [am-oy-bay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>récompenser, payer de retour, ce que l'on doit en retour</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμοιβή</b> <b>ῆς (ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> ce qui se fait <i>ou</i> se donne en échange :<br><b> 1</b> don en retour : ἀ. θυσιῶν, PLAT. <i>Conv. 202</i> e, faveur (des dieux) en retour de sacrifices, <i>d’où, en b. part,</i> récompense : σοὶ δ' ἄξιόν ἐστιν ἀμοιϐῆς, OD. <i>1, 318,</i> il est juste que tu sois récompensé ; ἀ. ἑκατόμϐης, OD. <i>3, 58,</i> récompense (accordée par un dieu) en échange d’une hécatombe ; <i>particul</i>. marque de reconnaissance, bon office, PD. <i>P. 2, 14 ;</i> EUR. <i>Or. 467 ; Hel. 159, etc. ;</i> PLUT. <i>M. 935</i> c, <i>etc. ; en mauv. part,</i> expiation, OD. <i>12, 382 ;</i> HÉS. <i>O. 332 ;</i> A. RH. <i>1, 619 ; ou</i> châtiment, PLUT. <i>Ant. 24, etc. ;</i><br><b> 2</b> lettre en réponse, HDT. <i>7, 160 ;</i><br><b>   II</b> alternance, succession (de maux, de fêtes, <i>etc</i>.) EUR. <i>El. 1147 ;</i> PLAT. <i>Leg. 653</i> d ;<br><b>   III</b> changement, transformation, DL. <i>9, 8</i>.<p><b>Étym</b>. ἀμείϐω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμοιβη - ἀμοιβή</font>\n<br><br>vient de ameibo (échanger)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G288":"<h1>ampelos</h1>\n<p>Strong n° 288 <i>Prononciation [am'-pel-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une vigne, un cep</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄμπελος</b> <b>ου (ἡ) :<br> 1</b> plant de vigne, vigne, OD. <i>9, 110, 133 ; 24, 246 ;</i> HH. <i>Bacch. 39 ;</i> PD. <i>O. 7, 2, etc. ;</i> ESCHL. <i>Pers. 615 ;</i> SOPH. <i>Tr. 704, O.C. 17, etc. ;</i> TH. <i>4, 90, etc. ;</i><br><b> 2</b> vignoble, EL. <i>N.A. 11, 32 ;</i><br><b> 3</b> <i>plante</i> marine (<i>clematis maritima</i> L.) TH. <i>H.P. 4, 6, 2 ;</i><br><b> 4</b> toit de défense, mantelet, <i>machine de siège (lat</i>. vinea) APD. POL. <i>15</i>.<p><b>Étym</b>. <i>p.-ê. pré-grec</i>.</p><b>Ἄμπελος</b> <b>ου (ὁ)</b> Ampélos :<br><b> 1</b> <i>prom. de Macédoine, etc</i>. HDT. <i>7, 122, etc. ;</i><br><b> 2</b> <i>h</i>. NONN. <i>D. 10, 178</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμπελος - ἄμπελος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G289":"<h1>ampelourgos</h1>\n<p>Strong n° 289 <i>Prononciation [am-pel-oor-gos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un vigneron, un viticulteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμπελουργός</b> <b>οῦ (ὁ, ἡ)</b> qui travaille la vigne, vigneron, AR. <i>Pax 190 ;</i> PLUT. <i>M. 1049</i> c ; NT. <i>Luc. 13, 7</i>.<p><b>Étym</b>. <i>contr. de</i> ἀμπελοεργός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμπελουργος - ἀμπελουργός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G290":"<h1>ampelon</h1>\n<p>Strong n° 290 <i>Prononciation [am-pel-ohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une vigne, vignoble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμπελών</b> <b>ῶνος (ὁ)</b> vignoble, ESCHN. <i>49, 13</i> (<i>v</i>. ἀμπελουργεῖον) ; DS. <i>4, 6 ;</i> PLUT. <i>Mar. 21 ;</i> SPT. <i>Gen. 9, 20, etc</i>.<p><b>Étym</b>. ἄμπελος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμπελων - ἀμπελών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 21 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (5)</li>\n<li>Luc (7)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G291":"<h1>Amplias</h1>\n<p>Strong n° 291 <i>Prononciation [am-plee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Amplias = « large, agrandi »\n<ol><li>un chrétien de Rome</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αμπλιας - Ἀμπλίας</font>\n<br><br>contracté du Latin ampliatus (agrandir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G292":"<h1>amunomai</h1>\n<p>Strong n° 292 <i>Prononciation [am-oo'-nom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>défendre\n<ol type=\"a\">\n<li>garder, protéger</li>\n<li>aider ou assister quelqu'un</li>\n<li>se défendre contre quelqu'un</li>\n<li>se venger de quelqu'un, rendre la pareille</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμυνομαι - ἀμύνομαι</font>\n<br><br>verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G293":"<h1>amphiblestron</h1>\n<p>Strong n° 293 <i>Prononciation [am-fib'-lace-tron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tout ce qui entoure et qui entrave les mouvements, tel que chaînes ou vêtements, un filet de pêche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμφίβληστρον</b> <b>ου (τὸ)</b> ce qu’on jette autour :<br><b> 1</b> entrave, lien, ESCHL. <i>Pr. 81 ;</i><br><b> 2</b> filet de chasse <i>ou</i> de pêche, HÉS. <i>Sc. 215 ;</i> HDT. <i>1, 141 ; 2, 95 ; en parl. du filet dont fut enlacé Agamemnon,</i> ESCHL. <i>Ag. 1382, etc. ;</i><br><b> 3</b> tunique, SOPH. <i>Tr. 1052 ;</i><br><b> 4</b> enceinte d’un temple, EUR. <i>I.T. 96 ;</i><br><b> 5</b> <i>adj</i>. ἀ. ῥάκη σώματος, EUR. <i>Hel. 1079,</i> haillons qui enveloppent le corps.<p><b>Étym</b>. ἀμφιϐάλλω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμφι-βληστρον - ἀμφίβληστρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – semble être le mot le plus général pour les filets de toute sorte\n<br><br> – un filet de pêche, filet à lancer, généralement en forme de poire\n<br><br> – un filet de pêche, une seine ou un filet à draguer</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G294":"<h1>amphiennumi</h1>\n<p>Strong n° 294 <i>Prononciation [am-fee-en'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se vêtir, s'habiller</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμφιέννυμι</b> <b>ἀμφι·έννυμι</b> <font color=\"brown\">[ῡ]</font> <font color=\"darkgreen\">(<i>impf</i>. ἠμφιέννυν <font color=\"brown\">[ῡ]</font>, <i>f</i>. ἀμφιέσω, <i>att</i>. ἀμφιῶ ; <i>ao</i>. ἠμφίεσα, <i>pf. inus. ; pass. pf</i>. ἠμφίεσμαι)</font> vêtir de, habiller de, <i>avec un seul rég. : acc. de chose :</i> εἵματα ἀμφ. OD. <i>5, 167 et 264 ; 18, 360,</i> couvrir (qqn) de vêtements ; <i>rar. acc. de pers</i>. ἀμφ. τινα, AR. <i>Pl. 935,</i> couvrir qqn (d’un vêtement); <i>d’ord. avec double acc</i>. τὸν ἑαυτοῦ χιτῶνα ἐκεῖνον ἠμφίεσε, XÉN. <i>Cyr. 1, 3, 17,</i> il le revêtit de sa propre tunique ; <i>de même</i> τινὰ ἀμφ. ἱμάτιον, PLAT. <i>Conv. 219</i> b, couvrir qqn d’un vêtement ; <i>cf</i>. PLAT. <i>Rsp. 420</i> e, <i>etc. ; rar. avec un acc. de pers. ou d’animal et un dat. de chose :</i> ἀμφ. αὐτὰ θριξὶ καὶ δέρμασιν, PLAT. <i>Prot. 321</i> a, couvrir ces animaux de poils et de peaux ;<br><b>Moy. ἀμφιέννυμαι</b> <font color=\"darkgreen\">(<i>f</i>. ἀμφιέσομαι, <i>ao</i>. ἠμφιεσάμην, <i>pf</i>. ἠμφίεσμαι)</font> se revêtir, se couvrir de : χιτῶνας, OD. <i>23, 131,</i> se vêtir de tuniques ; ἱμάτιον ἠμφίεσαι φαῦλον, XÉN. <i>Mem. 1, 6, 2,</i> tu es couvert d’un vêtement misérable ; στολὴν γυναικὸς ἠμφιεσμένον, AR. <i>Th. 92,</i> vêtu d’une robe de femme ; <i>abs</i>. ἀμφιέσομαι, XÉN. <i>Cyr. 4, 3, 20,</i> je m’habillerai ; ἠμφιεσμένοι καὶ ὑποδεδεμένοι, PLAT. <i>Rsp. 372</i> a, <i>Conv. 220</i> a, vêtus et chaussés ; <i>fig</i>. ἀρετὴν ἀντὶ ἱματίων ἀμφιέσονται, PLAT. <i>Rsp. 457</i> a (s’)ils s’enveloppent de vertu en guise de vêtements.<p><b>➼</b> <i>Pass. ao. part</i>. ἀμφιεσθείς, HDN <i>1, 10. Moy. ao. poét. 2 pl</i>. ἀμφιέσασθε, ESCHL. (ANTH. <i>12, 93</i>); <i>3 pl</i>. ἀμφιέσαντο, OD. <i>23, 142</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμφιεννυμι - ἀμφιέννυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G295":"<h1>Amphipolis</h1>\n<p>Strong n° 295 <i>Prononciation [am-fip'-ol-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Amphipolis = « ville entourée par les eaux »\n<ol><li>ville de Macédoine, ainsi appelée parce que le fleuve Strymon coule tout autour</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμφίπολις</b> <b>*ἀμφί·πολις</b>, <i>poét</i>. <b>ἀμφί·πτολις</b>, <i>acc</i>. <b>-ιν</b>, <i>adj. f</i>. qui est hors (<i>litt</i>. autour) de la ville, ESCHL. <i>Ch. 72</i>.<p><b>Étym</b>. ἀ. πόλις.</p><b>Ἀμφίπολις</b> <b>Ἀμφί·πολις, εως (ἡ)</b> Amphipolis, <i>v. de Thrace,</i> THC. <i>4, 102 ;</i> XÉN. <i>Hell. 4, 3, 1, etc</i>.<p><b>Étym</b>. ἀμφίπολις.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αμφιπολις - Ἀμφίπολις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G296":"<h1>amphodon</h1>\n<p>Strong n° 296 <i>Prononciation [am'-fod-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>carrefour de routes, coin de rues, quartier, faubourg (ensemble de maisons et de rues )</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄμφοδον</b> <b>ἄμφ·οδον, ου (τὸ)</b> <i>c</i>. ἄμφοδος, HYPÉR. (POLL. <i>9, 36</i>); SPT. <i>Jer. 17, 27 ;</i> NT. <i>Marc. 11, 4<br><b>ἄμφ·οδος, ου (ἡ)</b> rue avec les maisons qui la bordent, quartier d’une ville, CLÉM. <i>257 ;</i> GAL. <i>4, 266</i>.<br><span><b>Étym</b>. ἀ. ὁδός.</span></i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμφ-οδον - ἄμφοδον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G297":"<h1>amphoteros</h1>\n<p>Strong n° 297 <i>Prononciation [am-fot'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tous deux, l'un et l'autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμφότερος</b> <b>α, ον :<br>   I</b> l’un et l’autre (<i>p. opp. à</i> ἑκάτερος) <i>rare au sg</i>. ESCHL. <i>Pers. 131 ;</i> XÉN. <i>Cyr. 7, 4, 4 ;</i> PLAT. <i>Soph. 248</i> d, <i>etc. ;</i><br><b>   II</b> <i>d’ord. au duel</i> ἀμφοτέρω, IL. <i>5, 156, etc. ;</i> OD. <i>4, 282 ;</i> XÉN. <i>An. 1, 1, 1 ;</i> PLAT. <i>Parm. 143</i> c, <i>etc. ; ou au pl</i>. <b>ἀμφότεροι, αι, α :<br> 1</b> l’un et l’autre ensemble ; tous deux à la fois : <i>avec ou sans article dev. le subst :</i> οἱ στρατηγοὶ ἀμφότεροι, THC. <i>5, 74,</i> les deux généraux ensemble ; Καλλίγειτος καὶ Τιμαγόρας φυγάδες τῆς ἑαυτῶν ἀμφότεροι, THC. <i>8, 6,</i> Kalligeitos et Timagoras l’un et l’autre également exilés de leur pays ; <i>particul. en parl. des organes jumeaux :</i> ἀμφοτέροις βλέπειν (<i>s.-e</i>. ὄμμασι) CALL. <i>Ep. 31, 6,</i> regarder des deux yeux ; ἀμφοτέρῃσιν (<i>s.-e</i>. χερσί) OD. <i>10, 264,</i> des deux mains ; <i>adv</i>. κατ' ἀμφότερα, HDT. <i>7, 10 ;</i> PLAT. <i>Parm. 159</i> a, des deux côtés ; ἐπ' ἀμφότερα, HDT. <i>3, 87 ;</i> THC. <i>1, 83, etc. ;</i> PLAT. <i>Phædr. 274</i> e, dans les deux sens, des deux manières ; ἀπ' ἀμφοτέρων, HDT. <i>7, 97 ; ou</i> παρ' ἀμφοτέρων, DS. <i>16, 7,</i> des deux côtés ;<br><b> 2</b> <i>au sens plur</i>. les uns et les autres, les deux (groupes, armées, <i>etc</i>.) : ἐς μέσον ἀμφοτέρων συνίτην μεμαῶτε μάχεσθαι, IL. <i>6, 120,</i> tous deux s’avancèrent ensemble au milieu des deux armées, impatients de combattre ; <i>cf</i>. HÉS. <i>Sc. 176, Th. 678, etc. ;</i> ἀμφότεροι, <i>en parl. des ancêtres paternels et maternels,</i> EUR. <i>Alc. 920 ;</i><br><b>   III</b> <i>adv. :</i><br><b> 1</b> ἀμφοτέρῃ, des deux façons, HDT. <i>1, 75 ; ou</i> par les deux voies (par terre et par mer) HDT. <i>7, 10 ;</i><br><b> 2</b> <i>d’ord</i>. ἀμφότερον, de deux manières à la fois, ensemble : ἀμφότερον βασιλεύς τ' ἀγαθὸς κρατερός τ' αἰχμητής, IL. <i>3, 179,</i> à la fois bon roi et puissant guerrier ; <i>de même</i> ἀμφότερον… τε… καί, IL. <i>4, 60 ;</i> ἀμφότερον… τε… δέ, PD. <i>P. 4, 31, 3 ;</i> ἀμφότερον… καί… καί, PLAT. <i>Ion 541</i> b ; ἀμφότερον… τε… ἤ, PD. <i>O. 1, 29, 2,</i> à la fois… et… et ;<br><b> 3</b> ἀμφότερα, de deux manières à la fois : ἐνίκων τῇ αὐτῇ ἡμέρᾳ ἀμφότερα, THC. <i>1, 100,</i> ils étaient vainqueurs le même jour à la fois sur terre et sur mer ; <i>cf</i>. THC. <i>1, 13 et 112</i>.<p><b>➼</b> <i>Plur. avec un subst. duel :</i> χεῖρε πετάσσας ἀμφοτέρας, IL. <i>21, 115,</i> ayant ouvert les deux mains à la fois. — <i>Dans les inscr. att</i>. ἀμφότεροι <i>seul. avec un subst. précédé de l’art. :</i> τῶν ὑῶν ἀμφοτέρων, CIA. <i>2, 380, 4 (envir. 229 av. J.C</i>.); <i>cf. 622, 9 (commenc. du 2<sup>e</sup> siècle av. J.C</i>.); <i>v. Meisterh. p. 192, 40</i>.</p><p><b>Étym</b>. <i>compar. de</i> ἄμφω.</p><b>Ἀμφοτερός</b> <b>οῦ (ὁ)</b> Amphotéros, <i>h</i>. IL. <i>16, 415, etc</i>.<p><b>Étym</b>. <i>v</i>. ἀμφότερος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αμφοτερος - ἀμφότεροι</font>\n<br><br>comparatif de amphi (autour)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (5)</li>\n<li>Actes (2)</li>\n<li>Ephésiens (3)</li>\n</ul>\n</td></tr>\n</table>","G298":"<h1>amometos</h1>\n<p>Strong n° 298 <i>Prononciation [am-o'-may-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui ne peut être censuré, innocent, ce qui est sans reproche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀμώμητος</b> <b>ἀ·μώμητος, ος, ον</b>, irréprochable, IL. <i>12, 109 ;</i> HÉS. <i>Sc. 102 ;</i> PD. <i>P. 2, 74 ; rare et réc. en prose,</i> LGN <i>33, 5, etc</i>.<p><b>Étym</b>. ἀ, μωμέομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μωμητος - ἀμώμητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G299":"<h1>amomos</h1>\n<p>Strong n° 299 <i>Prononciation [am'-o-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans défaut, sans reproche, irréprochable\n<ol type=\"a\">\n<li>comme un sacrifice sans tache ou défaut</li>\n</ol>\n</li>\n<li>moralement : sans défaut, sans faute, irrépréhensible</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄμωμος</b> <b>ἄ·μωμος, ος, ον</b>, irréprochable, HDT. <i>2, 177 ;</i> ESCHL. <i>Pers. 185 ;</i> THCR. <i>Idyl. 18, 25, etc</i>.<p><b>Étym</b>. ἀ, μῶμος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-μωμος - ἄμωμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>"};
